< /*
<  * Hand every binary semaphore the task still holds to the next waiter, so
<  * that a task dying inside a critical section does not lock up the system.
<  */
< static void release_binsem(pcb_t *dead)
< {
<     for (int i = 0; i < dead->binsem_num; i++) {
<         binsem_node_t *node = &binsem_nodes[dead->binsem_id[i]];
< 
<         if (list_empty(&node->block_queue)) {
<             node->sem = 1;
<         } else {
<             /* the semaphore is handed over, so the woken task owns it */
<             list_node_t *waiter = node->block_queue.next;
<             pcb_t *new_owner = list_entry(waiter, pcb_t, list);
<             if (new_owner->binsem_num < BINSEM_NUMBER) {
<                 new_owner->binsem_id[new_owner->binsem_num++] = dead->binsem_id[i];
<             }
<             do_unblock(waiter);
<         }
<     }
<     dead->binsem_num = 0;
< }
< 
< /* give up everything the task holds and let whoever waits for it continue */
< static void release_resources(pcb_t *dead)
< {
<     release_binsem(dead);
< 
<     while (!list_empty(&dead->wait_list)) {
<         do_unblock(dead->wait_list.next);
<     }
< 
<     /* it may still sit on a block queue and have a sleep timer armed */
<     list_del(&dead->list);
<     list_del(&dead->timer.list);
< }
< 
< /*
<  * Throw away the address space of a dead process. This core may still be
<  * running on its page table, but the kernel half of every table is the same,
<  * so moving to the kernel one first is safe.
<  */
< static void release_address_space(pcb_t *dead)
< {
<     if (dead->pgdir == NULL || dead->pgdir == (PTE *)PGDIR_PA) {
<         return;
<     }
<     set_satp(SATP_MODE_SV39, 0, PGDIR_PA >> NORMAL_PAGE_SHIFT);
