#include <net.h>
#include <os/string.h>
#include <screen.h>
#include <emacps/xemacps_example.h>
#include <emacps/xemacps.h>
#include <assert.h>
#include <os/sched.h>
#include <os/mm.h>
#include <os/irq.h>

EthernetFrame rx_buffers[RXBD_CNT];
EthernetFrame tx_buffer;
uint32_t rx_len[RXBD_CNT];

/*
 * The device comes up with its interrupts masked - EmacPsInit leaves them that
 * way - so until a task asks for interrupt mode the driver polls.
 */
int net_poll_mode = 1;

LIST_HEAD(net_recv_queue);
LIST_HEAD(net_send_queue);

uintptr_t rx_curr = 0, rx_tail = 0;
int recv_transaction = 0,  send_transaction = 0;

uintptr_t _addr;
int _num_packet;
size_t* _frLength;

/* the interrupts the driver lives on while it is running in interrupt mode */
#define NET_IRQ_MASK                                     \
    (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK | \
     (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK)

/*
 * A user buffer is contiguous in the address space of its owner, but the pages
 * behind it are not, so it is copied one page at a time. The pages are created
 * on the way: the buffer of a program usually is memory it never touched.
 */
static void copy_to_user_buffer(uintptr_t va, const uint8_t *src, size_t length,
                                uintptr_t pgdir)
{
    while (length > 0) {
        size_t chunk = PAGE_SIZE - (va & (PAGE_SIZE - 1));
        if (chunk > length) {
            chunk = length;
        }
        memcpy((uint8_t *)alloc_page_helper(va, pgdir), (uint8_t *)src, chunk);
        va += chunk;
        src += chunk;
        length -= chunk;
    }
}

static void copy_from_user_buffer(uint8_t *dest, uintptr_t va, size_t length,
                                  uintptr_t pgdir)
{
    while (length > 0) {
        size_t chunk = PAGE_SIZE - (va & (PAGE_SIZE - 1));
        if (chunk > length) {
            chunk = length;
        }
        memcpy(dest, (uint8_t *)alloc_page_helper(va, pgdir), chunk);
        va += chunk;
        dest += chunk;
        length -= chunk;
    }
}

long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    if (num_packet <= 0) {
        return 0;
    }
    if (num_packet > RXBD_CNT) {
        num_packet = RXBD_CNT;
    }

    disable_preempt();

    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;

    /*
     * The packets are handed over through the kernel's own mapping of the
     * buffer - in interrupt mode the copy happens while any address space may
     * be the one loaded - so all of its pages have to exist before the DMA
     * engine starts.
     */
    for (uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE); va < addr + length;
         va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }
    uintptr_t length_end = (uintptr_t)frLength + num_packet * sizeof(size_t);
    for (uintptr_t va = ROUNDDOWN((uintptr_t)frLength, PAGE_SIZE);
         va < length_end; va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }

    _addr = alloc_page_helper(addr, pgdir);
    _num_packet = num_packet;
    _frLength = (size_t *)alloc_page_helper((uintptr_t)frLength, pgdir);

    /* hand the receive descriptors over to the DMA engine */
    if (!net_poll_mode) {
        recv_transaction = 1;
    }
    EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);

    if (net_poll_mode) {
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);

        uintptr_t curr = addr;
        for (int i = 0; i < num_packet; i++) {
            copy_to_user_buffer(curr, (uint8_t *)&rx_buffers[i], rx_len[i], pgdir);
            *(size_t *)alloc_page_helper((uintptr_t)&frLength[i], pgdir) = rx_len[i];
            curr += rx_len[i];
        }
    }
    else {
        /* XEmacPsRecvHandler copies the packets in and wakes us up */
        do_block(&current_running[cpu_id]->list, &net_recv_queue);
        scheduler();
    }

    long received = 0;
    for (int i = 0; i < num_packet; i++) {
        received += rx_len[i];
    }

    enable_preempt();
    return received;
}

void do_net_send(uintptr_t addr, size_t length)
{
    if (length == 0) {
        return;
    }
    if (length > sizeof(EthernetFrame)) {
        length = sizeof(EthernetFrame);
    }

    disable_preempt();

    /* the DMA engine reads out of the buffer the descriptor points to */
    copy_from_user_buffer((uint8_t *)&tx_buffer, addr, length,
                          (uintptr_t)current_running[cpu_id]->pgdir);

    if (!net_poll_mode) {
        send_transaction = 1;
    }
    EmacPsSend(&EmacPsInstance, &tx_buffer, length);

    if (net_poll_mode) {
        EmacPsWaitSend(&EmacPsInstance);
    }
    else {
        /* XEmacPsSendHandler wakes us up once the frame has left */
        do_block(&current_running[cpu_id]->list, &net_send_queue);
        scheduler();
    }

    enable_preempt();
}

void do_net_irq_mode(int mode)
{
    disable_preempt();

    net_poll_mode = (mode == 0);
    if (net_poll_mode) {
        /* the device is not going to wake anybody up any more */
        XEmacPs_IntDisable(&EmacPsInstance, NET_IRQ_MASK);
        recv_transaction = 0;
        send_transaction = 0;
    }
    else {
        XEmacPs_IntEnable(&EmacPsInstance, NET_IRQ_MASK);
    }

    enable_preempt();
}

