11	ptr_t kernel_memCurr = KERNEL_MEM_BEGIN;
12	ptr_t user_memCurr = USER_MEM_BEGIN;
13	
14	user_page_t user_page[USER_PAGE_NUM];
15	shm_page_t shm_page[SHM_PAGE_NUM];
16	disk_page_t disk_page[DISK_PAGE_NUM];
17	pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];
