19	/*
20	 * User pages are mapped rwx: a user program is linked into a single loadable
21	 * segment that holds its code and its data, so the loader can not tell them
22	 * apart.
23	 */
24	#define USER_PAGE_ATTRIBUTE \
25	    (_PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC | _PAGE_USER)
26	
27	/* the swap area of the SD card is addressed in sectors */
28	#define SECTOR_SIZE 512
29	#define SECTORS_PER_PAGE (PAGE_SIZE / SECTOR_SIZE)
30	
31	/*
32	 * Share region of the user address space (see the layout below). The code of
33	 * every user program is linked at 0x10000, but its ELF header may live in the
34	 * page just below it, so the code region starts one page earlier.
35	 */
36	#define USER_SHARE_BEGIN 0x1000lu
37	#define USER_SHARE_END 0xf000lu
38	#define USER_CODE_BEGIN 0xf000lu
39	#define USER_CODE_END 0x14000lu
40	
41	/* the user half of the root page table, the kernel owns the other one */
42	#define USER_PGDIR_ENTRY_NUM (NUM_PTE_ENTRY / 2)
43	
44	// returns pa
45	PTE* alloc_pgdir_page()
46	{
47	    int i;
48	    for(i = 0; i < PGDIR_PAGE_NUM; i++){
49	        if(pgdir_page[i].valid == 0){
50	            break;
51	        }
52	    }
53	    assert(i != PGDIR_PAGE_NUM);
54	    pgdir_page[i].valid = 1;
55	    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
56	    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
57	    return ret;
58	}
59	
60	void free_pgdir_page(uintptr_t addr)
61	{
62	    int i = (addr - FREE_PGDIR_ADDR) / PAGE_SIZE;
63	    pgdir_page[i].valid = 0;
64	}
65	
66	int pa2num(uintptr_t pa)
67	{
68	    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
69	}
70	ptr_t num2pa(int num)
71	{
72	    return (USER_MEM_BEGIN + num * PAGE_SIZE);
73	}
74	
75	/*
76	 * Walk `pgdir` (a pa) down to the last level entry which maps `va`. Levels
77	 * that are missing on the way are created when `create` is set, otherwise the
78	 * walk gives up and returns NULL.
79	 */
80	static PTE* find_pte(uintptr_t va, PTE *pgdir, int create)
81	{
82	    uintptr_t vpn[2] = {(va >> VPN2_SHIFT) & VPN_MASK,
83	                        (va >> VPN1_SHIFT) & VPN_MASK};
84	    PTE *table = (PTE*)pa2kva((uintptr_t)pgdir);
85	
86	    for(int level = 0; level < 2; level++){
87	        PTE *entry = table + vpn[level];
88	        if(get_attribute(*entry, _PAGE_PRESENT) == 0){
89	            if(!create){
90	                return NULL;
91	            }
92	            /* a directory entry carries no permission bits of its own */
93	            PTE *next = alloc_pgdir_page();
94	            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
95	            set_attribute(entry, _PAGE_PRESENT);
96	        }
97	        table = (PTE*)pa2kva(get_pa(*entry));
98	    }
99	
100	    return table + ((va >> VPN0_SHIFT) & VPN_MASK);
101	}
102	
103	/* hand `pa` to `entry` as a writable user page */
104	static void set_leaf_page(PTE *entry, ptr_t pa)
105	{
106	    set_pfn(entry, pa >> NORMAL_PAGE_SHIFT);
107	    clear_attribute(entry, _PAGE_SOFT);
108	    set_attribute(entry, USER_PAGE_ATTRIBUTE);
109	}
110	
111	// returns pa
112	ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
113	{
114	    int i;
115	    for(i = 0; i < USER_PAGE_NUM; i++){
116	        if(user_page[i].valid == 0){
117	            break;
118	        }
119	    }
120	    if(i == USER_PAGE_NUM){
121	        /* memory is full: make room by moving somebody else to the disk */
122	        ptr_t victim = selete_page();
123	        assert(victim != 0);
124	        write_to_sd(victim);
125	        i = pa2num(victim);
126	    }
127	
128	    user_page[i].valid = 1;
129	    user_page[i].pin = pin;
130	    /* remembering the owning entry is what makes the page swappable later */
131	    user_page[i].pgtable = pgtable;
132	    return num2pa(i);
133	}
134	
135	// baseAddr is pa
136	void free_user_page(ptr_t baseAddr)
137	{
138	    user_page[pa2num(baseAddr)].valid = 0;
139	}
140	
141	// returns pa
142	void *kmalloc(size_t size)
143	{
144	    // align 4
145	    ptr_t ret = ROUND(kernel_memCurr, 4);
146	    kernel_memCurr = ret + size;
147	    return (void*)ret;
148	}
149	
150	// select a user page to write to disk (NRU), returns pa
151	ptr_t selete_page()
152	{
153	    int victim = -1;
154	    int victim_class = 4;
155	
156	    /*
157	     * NRU: rank every candidate by its (accessed, dirty) pair and evict the
158	     * lowest class found, preferring a page that has neither been used nor
159	     * written since the last sweep. The reference bits are cleared on the way
160	     * out, so the next sweep sees what happened in between.
161	     */
162	    for(int i = 0; i < USER_PAGE_NUM; i++){
163	        if(user_page[i].valid == 0 || user_page[i].pin ||
164	           user_page[i].pgtable == NULL){
165	            continue;
166	        }
167	        PTE entry = *user_page[i].pgtable;
168	        int page_class = (get_attribute(entry, _PAGE_ACCESSED) ? 2 : 0) +
169	                         (get_attribute(entry, _PAGE_DIRTY) ? 1 : 0);
170	        if(page_class < victim_class){
171	            victim_class = page_class;
172	            victim = i;
173	        }
174	        clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
175	    }
176	
177	    if(victim < 0){
178	        /* everything left is pinned, there is nothing we may take away */
179	        return 0;
180	    }
181	
182	    flush_tlb_all();
183	    return num2pa(victim);
184	}
185	
186	void write_to_sd(ptr_t pa)
187	{
188	    int slot;
189	    for(slot = 0; slot < DISK_PAGE_NUM; slot++){
190	        if(disk_page[slot].valid == 0){
191	            break;
192	        }
193	    }
194	    assert(slot != DISK_PAGE_NUM);
195	    disk_page[slot].valid = 1;
196	
197	    /* the SBI runs in machine mode, so it wants the physical address */
198	    sbi_sd_write((unsigned int)pa, SECTORS_PER_PAGE,
199	                 SWAP_BEGIN + slot * SECTORS_PER_PAGE);
200	
201	    /*
202	     * The owner has to fault the next time it touches the page, so its entry
203	     * keeps the swap slot instead of a frame number and is marked as
204	     * "invalid, but known to the kernel" with the software bit.
205	     */
206	    PTE *entry = user_page[pa2num(pa)].pgtable;
207	    if(entry != NULL){
208	        set_pfn(entry, slot);
209	        clear_attribute(entry, _PAGE_PRESENT | _PAGE_ACCESSED | _PAGE_DIRTY);
210	        set_attribute(entry, _PAGE_SOFT);
211	    }
212	
213	    free_user_page(pa);
214	    /* the page may still be mapped by the task running on the other core */
215	    flush_tlb_all();
216	}
