229	/* give `va` a zeroed page of its own in `pgdir`, returns the kva of the page */
230	static uintptr_t map_user_page(uintptr_t va, PTE *pgdir)
231	{
232	    PTE *entry = find_pte(va, pgdir, 1);
233	    ptr_t pa = alloc_user_page(0, entry);
234	
235	    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
236	    set_leaf_page(entry, pa);
237	    return pa2kva(pa);
238	}
