240	/*
241	 * Virtual Memory Layout
242	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
243	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
244	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
245	 */
246	PTE* init_page_table()
247	{
248	    PTE *pgdir = alloc_pgdir_page();
249	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
250	    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
251	
252	    /*
253	     * Every address space shares the kernel half of the root table: the
254	     * kernel keeps running - and keeps taking traps - at its own addresses
255	     * after satp has been switched to this table.
256	     */
257	    for(int i = USER_PGDIR_ENTRY_NUM; i < NUM_PTE_ENTRY; i++){
258	        pgdir_kva[i] = kernel_pgdir_kva[i];
259	    }
260	
261	    /*
262	     * The loader only walks the page table, so the pages of the program have
263	     * to be there before its ELF image is copied in.
264	     */
265	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
266	        map_user_page(va, pgdir);
267	    }
268	    /* one page of stack, the rest of it is faulted in when it is needed */
269	    map_user_page(USER_STACK_ADDR - PAGE_SIZE, pgdir);
270	
271	    return pgdir;
272	}
