274	/* release whatever a last level entry owns: memory, a swap slot or nothing */
275	static void free_leaf_page(PTE *entry)
276	{
277	    if(get_attribute(*entry, _PAGE_PRESENT)){
278	        uintptr_t pa = get_pa(*entry);
279	        int shm;
280	        for(shm = 0; shm < SHM_PAGE_NUM; shm++){
281	            if(shm_page[shm].count > 0 && shm_page[shm].pa == pa){
282	                break;
283	            }
284	        }
285	        if(shm < SHM_PAGE_NUM){
286	            /* a shared page only goes away with its last user */
287	            if(--shm_page[shm].count == 0){
288	                free_user_page(pa);
289	            }
290	        }
291	        else if(pa >= USER_MEM_BEGIN && pa < USER_MEM_END){
292	            free_user_page(pa);
293	        }
294	    }
295	    else if(get_attribute(*entry, _PAGE_SOFT)){
296	        /* the page was swapped out, its slot on the disk is free again */
297	        disk_page[get_pfn(*entry)].valid = 0;
298	    }
299	    *entry = 0;
300	}
301	
302	void free_process_user_page(PTE* pgdir)
303	{
304	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
305	
306	    /* only the user half, the kernel half is shared with everybody else */
307	    for(int i = 0; i < USER_PGDIR_ENTRY_NUM; i++){
308	        if(get_attribute(pgdir_kva[i], _PAGE_PRESENT) == 0){
309	            continue;
310	        }
311	        uintptr_t second_level_pa = get_pa(pgdir_kva[i]);
312	        PTE *second_level_pgdir = (PTE*)pa2kva(second_level_pa);
313	
314	        for(int j = 0; j < NUM_PTE_ENTRY; j++){
315	            if(get_attribute(second_level_pgdir[j], _PAGE_PRESENT) == 0){
316	                continue;
317	            }
318	            uintptr_t last_level_pa = get_pa(second_level_pgdir[j]);
319	            PTE *last_level_pgdir = (PTE*)pa2kva(last_level_pa);
320	
321	            for(int k = 0; k < NUM_PTE_ENTRY; k++){
322	                if(last_level_pgdir[k] != 0){
323	                    free_leaf_page(&last_level_pgdir[k]);
324	                }
325	            }
326	            second_level_pgdir[j] = 0;
327	            free_pgdir_page(last_level_pa);
328	        }
329	        pgdir_kva[i] = 0;
330	        free_pgdir_page(second_level_pa);
331	    }
332	
333	    free_pgdir_page((uintptr_t)pgdir);
334	    local_flush_tlb_all();
335	}
