337	// pgdir is pa. if va is not mapped, then mapped it
338	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
339	{
340	    PTE *entry = find_pte(va, (PTE*)pgdir, 1);
341	
342	    if(get_attribute(*entry, _PAGE_PRESENT) == 0){
343	        if(get_attribute(*entry, _PAGE_SOFT)){
344	            /* the page is on the disk, it has to come back before it is used */
345	            int slot = get_pfn(*entry);
346	            ptr_t pa = alloc_user_page(0, entry);
347	            sbi_sd_read((unsigned int)pa, SECTORS_PER_PAGE,
348	                        SWAP_BEGIN + slot * SECTORS_PER_PAGE);
349	            disk_page[slot].valid = 0;
350	            set_leaf_page(entry, pa);
351	        }
352	        else{
353	            map_user_page(va, (PTE*)pgdir);
354	        }
355	        local_flush_tlb_page(ROUNDDOWN(va, PAGE_SIZE));
356	    }
357	
358	    return pa2kva(get_pa(*entry) | (va & PAGE_OFFSET_MASK));
359	}
