361	uintptr_t shm_page_get(int key)
362	{
363	    disable_preempt();
364	
365	    int index = (int)((uint64_t)(unsigned int)key % SHM_PAGE_NUM);
366	    if(shm_page[index].count == 0){
367	        /* the first user of the key brings the page into being */
368	        shm_page[index].pa = alloc_user_page(1, NULL);
369	        memset((void*)pa2kva(shm_page[index].pa), 0, PAGE_SIZE);
370	    }
371	
372	    /*
373	     * The page is attached to the first free address of the share region, so
374	     * a process which detached it and then used the address for something
375	     * else still gets a working mapping somewhere else.
376	     */
377	    PTE *pgdir = current_running[cpu_id]->pgdir;
378	    for(uintptr_t va = USER_SHARE_BEGIN; va < USER_SHARE_END; va += PAGE_SIZE){
379	        PTE *entry = find_pte(va, pgdir, 1);
380	        if(*entry == 0){
381	            shm_page[index].count++;
382	            set_leaf_page(entry, shm_page[index].pa);
383	            local_flush_tlb_page(va);
384	            enable_preempt();
385	            return va;
386	        }
387	    }
388	
389	    /* the share region of this process is full */
390	    enable_preempt();
391	    return 0;
392	}
