394	void shm_page_dt(uintptr_t addr)
395	{
396	    disable_preempt();
397	
398	    PTE *entry = find_pte(ROUNDDOWN(addr, PAGE_SIZE),
399	                          current_running[cpu_id]->pgdir, 0);
400	    if(entry == NULL || get_attribute(*entry, _PAGE_PRESENT) == 0){
401	        enable_preempt();
402	        return;
403	    }
404	
405	    uintptr_t pa = get_pa(*entry);
406	    *entry = 0;
407	    local_flush_tlb_page(ROUNDDOWN(addr, PAGE_SIZE));
408	
409	    for(int i = 0; i < SHM_PAGE_NUM; i++){
410	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
411	            if(--shm_page[i].count == 0){
412	                free_user_page(pa);
413	            }
414	            break;
415	        }
416	    }
417	
418	    enable_preempt();
419	}
