421	/*
422	 * A fault in the kernel half means this address space was created before the
423	 * mapping was: ioremap() hands out device memory long after the first process
424	 * has been started. Catching up is all it takes, the kernel half is shared.
425	 */
426	static int sync_kernel_page_table(uintptr_t va, PTE *pgdir)
427	{
428	    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
429	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
430	    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
431	
432	    if(vpn2 < USER_PGDIR_ENTRY_NUM || pgdir_kva[vpn2] == kernel_pgdir_kva[vpn2]){
433	        return 0;
434	    }
435	    pgdir_kva[vpn2] = kernel_pgdir_kva[vpn2];
436	    local_flush_tlb_all();
437	    return 1;
438	}
