440	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
441	{
442	    /* only the user half of the address space is paged on demand */
443	    if(stval > VA_MASK || (stval >> VPN2_SHIFT) >= USER_PGDIR_ENTRY_NUM){
444	        if(!sync_kernel_page_table(stval, current_running[cpu_id]->pgdir)){
445	            handle_other(regs, stval, cause);
446	        }
447	        return;
448	    }
449	
450	    disable_preempt();
451	
452	    uintptr_t va = ROUNDDOWN(stval, PAGE_SIZE);
453	    PTE *entry = find_pte(va, current_running[cpu_id]->pgdir, 1);
454	
455	    if(get_attribute(*entry, _PAGE_PRESENT)){
456	        /*
457	         * The mapping is already there, so the fault only reports a missing
458	         * accessed/dirty bit on a machine which does not maintain them.
459	         */
460	        set_attribute(entry, _PAGE_ACCESSED);
461	        if(cause == EXCC_STORE_PAGE_FAULT){
462	            set_attribute(entry, _PAGE_DIRTY);
463	        }
464	    }
465	    else if(get_attribute(*entry, _PAGE_SOFT)){
466	        /* the page lives on the disk, bring it back into memory */
467	        int slot = get_pfn(*entry);
468	        ptr_t pa = alloc_user_page(0, entry);
469	        sbi_sd_read((unsigned int)pa, SECTORS_PER_PAGE,
470	                    SWAP_BEGIN + slot * SECTORS_PER_PAGE);
471	        disk_page[slot].valid = 0;
472	        set_leaf_page(entry, pa);
473	    }
474	    else{
475	        /* the first touch of the page: it starts out empty */
476	        ptr_t pa = alloc_user_page(0, entry);
477	        memset((void*)pa2kva(pa), 0, PAGE_SIZE);
478	        set_leaf_page(entry, pa);
479	    }
480	
481	    local_flush_tlb_page(va);
482	    enable_preempt();
483	}
