#include <os/list.h>
#include <os/mm.h>
#include <os/sched.h>
#include <pgtable.h>
#include <os/string.h>
#include <os/sched.h>
#include <os/irq.h>
#include <assert.h>
#include <os/ioremap.h>

ptr_t kernel_memCurr = KERNEL_MEM_BEGIN;
ptr_t user_memCurr = USER_MEM_BEGIN;

user_page_t user_page[USER_PAGE_NUM];
shm_page_t shm_page[SHM_PAGE_NUM];
disk_page_t disk_page[DISK_PAGE_NUM];
pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];

/*
 * User pages are mapped rwx: a user program is linked into a single loadable
 * segment that holds its code and its data, so the loader can not tell them
 * apart.
 */
#define USER_PAGE_ATTRIBUTE \
    (_PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC | _PAGE_USER)

/* the swap area of the SD card is addressed in sectors */
#define SECTOR_SIZE 512
#define SECTORS_PER_PAGE (PAGE_SIZE / SECTOR_SIZE)

/*
 * Share region of the user address space (see the layout below). The code of
 * every user program is linked at 0x10000, but its ELF header may live in the
 * page just below it, so the code region starts one page earlier.
 */
#define USER_SHARE_BEGIN 0x1000lu
#define USER_SHARE_END 0xf000lu
#define USER_CODE_BEGIN 0xf000lu
#define USER_CODE_END 0x14000lu

/* the user half of the root page table, the kernel owns the other one */
#define USER_PGDIR_ENTRY_NUM (NUM_PTE_ENTRY / 2)

// returns pa
PTE* alloc_pgdir_page()
{
    int i;
    for(i = 0; i < PGDIR_PAGE_NUM; i++){
        if(pgdir_page[i].valid == 0){
            break;
        }
    }
    assert(i != PGDIR_PAGE_NUM);
    pgdir_page[i].valid = 1;
    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
    return ret;
}

void free_pgdir_page(uintptr_t addr)
{
    int i = (addr - FREE_PGDIR_ADDR) / PAGE_SIZE;
    pgdir_page[i].valid = 0;
}

int pa2num(uintptr_t pa)
{
    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
}
ptr_t num2pa(int num)
{
    return (USER_MEM_BEGIN + num * PAGE_SIZE);
}

/*
 * Walk `pgdir` (a pa) down to the last level entry which maps `va`. Levels
 * that are missing on the way are created when `create` is set, otherwise the
 * walk gives up and returns NULL.
 */
static PTE* find_pte(uintptr_t va, PTE *pgdir, int create)
{
    uintptr_t vpn[2] = {(va >> VPN2_SHIFT) & VPN_MASK,
                        (va >> VPN1_SHIFT) & VPN_MASK};
    PTE *table = (PTE*)pa2kva((uintptr_t)pgdir);

    for(int level = 0; level < 2; level++){
        PTE *entry = table + vpn[level];
        if(get_attribute(*entry, _PAGE_PRESENT) == 0){
            if(!create){
                return NULL;
            }
            /* a directory entry carries no permission bits of its own */
            PTE *next = alloc_pgdir_page();
            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
            set_attribute(entry, _PAGE_PRESENT);
        }
        table = (PTE*)pa2kva(get_pa(*entry));
    }

    return table + ((va >> VPN0_SHIFT) & VPN_MASK);
}

/* hand `pa` to `entry` as a writable user page */
static void set_leaf_page(PTE *entry, ptr_t pa)
{
    set_pfn(entry, pa >> NORMAL_PAGE_SHIFT);
    clear_attribute(entry, _PAGE_SOFT);
    set_attribute(entry, USER_PAGE_ATTRIBUTE);
}

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }
    if(i == USER_PAGE_NUM){
        /* memory is full: make room by moving somebody else to the disk */
        ptr_t victim = selete_page();
        assert(victim != 0);
        write_to_sd(victim);
        i = pa2num(victim);
    }

    user_page[i].valid = 1;
    user_page[i].pin = pin;
    /* remembering the owning entry is what makes the page swappable later */
    user_page[i].pgtable = pgtable;
    return num2pa(i);
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
}

// returns pa
void *kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(kernel_memCurr, 4);
    kernel_memCurr = ret + size;
    return (void*)ret;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    int victim = -1;
    int victim_class = 4;

    /*
     * NRU: rank every candidate by its (accessed, dirty) pair and evict the
     * lowest class found, preferring a page that has neither been used nor
     * written since the last sweep. The reference bits are cleared on the way
     * out, so the next sweep sees what happened in between.
     */
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0 || user_page[i].pin ||
           user_page[i].pgtable == NULL){
            continue;
        }
        PTE entry = *user_page[i].pgtable;
        int page_class = (get_attribute(entry, _PAGE_ACCESSED) ? 2 : 0) +
                         (get_attribute(entry, _PAGE_DIRTY) ? 1 : 0);
        if(page_class < victim_class){
            victim_class = page_class;
            victim = i;
        }
        clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
    }

    if(victim < 0){
        /* everything left is pinned, there is nothing we may take away */
        return 0;
    }

    flush_tlb_all();
    return num2pa(victim);
}

void write_to_sd(ptr_t pa)
{
    int slot;
    for(slot = 0; slot < DISK_PAGE_NUM; slot++){
        if(disk_page[slot].valid == 0){
            break;
        }
    }
    assert(slot != DISK_PAGE_NUM);
    disk_page[slot].valid = 1;

    /* the SBI runs in machine mode, so it wants the physical address */
    sbi_sd_write((unsigned int)pa, SECTORS_PER_PAGE,
                 SWAP_BEGIN + slot * SECTORS_PER_PAGE);

    /*
     * The owner has to fault the next time it touches the page, so its entry
     * keeps the swap slot instead of a frame number and is marked as
     * "invalid, but known to the kernel" with the software bit.
     */
    PTE *entry = user_page[pa2num(pa)].pgtable;
    if(entry != NULL){
        set_pfn(entry, slot);
        clear_attribute(entry, _PAGE_PRESENT | _PAGE_ACCESSED | _PAGE_DIRTY);
        set_attribute(entry, _PAGE_SOFT);
    }

    free_user_page(pa);
    /* the page may still be mapped by the task running on the other core */
    flush_tlb_all();
}

unsigned long free_page_num()
{
    unsigned long ret = 0;
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            ret++;
        }
    }
    return ret;
}

/* give `va` a zeroed page of its own in `pgdir`, returns the kva of the page */
static uintptr_t map_user_page(uintptr_t va, PTE *pgdir)
{
    PTE *entry = find_pte(va, pgdir, 1);
    ptr_t pa = alloc_user_page(0, entry);

    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
    set_leaf_page(entry, pa);
    return pa2kva(pa);
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);

    /*
     * Every address space shares the kernel half of the root table: the
     * kernel keeps running - and keeps taking traps - at its own addresses
     * after satp has been switched to this table.
     */
    for(int i = USER_PGDIR_ENTRY_NUM; i < NUM_PTE_ENTRY; i++){
        pgdir_kva[i] = kernel_pgdir_kva[i];
    }

    /*
     * The loader only walks the page table, so the pages of the program have
     * to be there before its ELF image is copied in.
     */
    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
        map_user_page(va, pgdir);
    }
    /* one page of stack, the rest of it is faulted in when it is needed */
    map_user_page(USER_STACK_ADDR - PAGE_SIZE, pgdir);

    return pgdir;
}

/* release whatever a last level entry owns: memory, a swap slot or nothing */
static void free_leaf_page(PTE *entry)
{
    if(get_attribute(*entry, _PAGE_PRESENT)){
        uintptr_t pa = get_pa(*entry);
        int shm;
        for(shm = 0; shm < SHM_PAGE_NUM; shm++){
            if(shm_page[shm].count > 0 && shm_page[shm].pa == pa){
                break;
            }
        }
        if(shm < SHM_PAGE_NUM){
            /* a shared page only goes away with its last user */
            if(--shm_page[shm].count == 0){
                free_user_page(pa);
            }
        }
        else if(pa >= USER_MEM_BEGIN && pa < USER_MEM_END){
            free_user_page(pa);
        }
    }
    else if(get_attribute(*entry, _PAGE_SOFT)){
        /* the page was swapped out, its slot on the disk is free again */
        disk_page[get_pfn(*entry)].valid = 0;
    }
    *entry = 0;
}

void free_process_user_page(PTE* pgdir)
{
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);

    /* only the user half, the kernel half is shared with everybody else */
    for(int i = 0; i < USER_PGDIR_ENTRY_NUM; i++){
        if(get_attribute(pgdir_kva[i], _PAGE_PRESENT) == 0){
            continue;
        }
        uintptr_t second_level_pa = get_pa(pgdir_kva[i]);
        PTE *second_level_pgdir = (PTE*)pa2kva(second_level_pa);

        for(int j = 0; j < NUM_PTE_ENTRY; j++){
            if(get_attribute(second_level_pgdir[j], _PAGE_PRESENT) == 0){
                continue;
            }
            uintptr_t last_level_pa = get_pa(second_level_pgdir[j]);
            PTE *last_level_pgdir = (PTE*)pa2kva(last_level_pa);

            for(int k = 0; k < NUM_PTE_ENTRY; k++){
                if(last_level_pgdir[k] != 0){
                    free_leaf_page(&last_level_pgdir[k]);
                }
            }
            second_level_pgdir[j] = 0;
            free_pgdir_page(last_level_pa);
        }
        pgdir_kva[i] = 0;
        free_pgdir_page(second_level_pa);
    }

    free_pgdir_page((uintptr_t)pgdir);
    local_flush_tlb_all();
}

// pgdir is pa. if va is not mapped, then mapped it
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    PTE *entry = find_pte(va, (PTE*)pgdir, 1);

    if(get_attribute(*entry, _PAGE_PRESENT) == 0){
        if(get_attribute(*entry, _PAGE_SOFT)){
            /* the page is on the disk, it has to come back before it is used */
            int slot = get_pfn(*entry);
            ptr_t pa = alloc_user_page(0, entry);
            sbi_sd_read((unsigned int)pa, SECTORS_PER_PAGE,
                        SWAP_BEGIN + slot * SECTORS_PER_PAGE);
            disk_page[slot].valid = 0;
            set_leaf_page(entry, pa);
        }
        else{
            map_user_page(va, (PTE*)pgdir);
        }
        local_flush_tlb_page(ROUNDDOWN(va, PAGE_SIZE));
    }

    return pa2kva(get_pa(*entry) | (va & PAGE_OFFSET_MASK));
}

uintptr_t shm_page_get(int key)
{
    disable_preempt();

    int index = (int)((uint64_t)(unsigned int)key % SHM_PAGE_NUM);
    if(shm_page[index].count == 0){
        /* the first user of the key brings the page into being */
        shm_page[index].pa = alloc_user_page(1, NULL);
        memset((void*)pa2kva(shm_page[index].pa), 0, PAGE_SIZE);
    }

    /*
     * The page is attached to the first free address of the share region, so
     * a process which detached it and then used the address for something
     * else still gets a working mapping somewhere else.
     */
    PTE *pgdir = current_running[cpu_id]->pgdir;
    for(uintptr_t va = USER_SHARE_BEGIN; va < USER_SHARE_END; va += PAGE_SIZE){
        PTE *entry = find_pte(va, pgdir, 1);
        if(*entry == 0){
            shm_page[index].count++;
            set_leaf_page(entry, shm_page[index].pa);
            local_flush_tlb_page(va);
            enable_preempt();
            return va;
        }
    }

    /* the share region of this process is full */
    enable_preempt();
    return 0;
}

void shm_page_dt(uintptr_t addr)
{
    disable_preempt();

    PTE *entry = find_pte(ROUNDDOWN(addr, PAGE_SIZE),
                          current_running[cpu_id]->pgdir, 0);
    if(entry == NULL || get_attribute(*entry, _PAGE_PRESENT) == 0){
        enable_preempt();
        return;
    }

    uintptr_t pa = get_pa(*entry);
    *entry = 0;
    local_flush_tlb_page(ROUNDDOWN(addr, PAGE_SIZE));

    for(int i = 0; i < SHM_PAGE_NUM; i++){
        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
            if(--shm_page[i].count == 0){
                free_user_page(pa);
            }
            break;
        }
    }

    enable_preempt();
}

/*
 * A fault in the kernel half means this address space was created before the
 * mapping was: ioremap() hands out device memory long after the first process
 * has been started. Catching up is all it takes, the kernel half is shared.
 */
static int sync_kernel_page_table(uintptr_t va, PTE *pgdir)
{
    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);

    if(vpn2 < USER_PGDIR_ENTRY_NUM || pgdir_kva[vpn2] == kernel_pgdir_kva[vpn2]){
        return 0;
    }
    pgdir_kva[vpn2] = kernel_pgdir_kva[vpn2];
    local_flush_tlb_all();
    return 1;
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    /* only the user half of the address space is paged on demand */
    if(stval > VA_MASK || (stval >> VPN2_SHIFT) >= USER_PGDIR_ENTRY_NUM){
        if(!sync_kernel_page_table(stval, current_running[cpu_id]->pgdir)){
            handle_other(regs, stval, cause);
        }
        return;
    }

    disable_preempt();

    uintptr_t va = ROUNDDOWN(stval, PAGE_SIZE);
    PTE *entry = find_pte(va, current_running[cpu_id]->pgdir, 1);

    if(get_attribute(*entry, _PAGE_PRESENT)){
        /*
         * The mapping is already there, so the fault only reports a missing
         * accessed/dirty bit on a machine which does not maintain them.
         */
        set_attribute(entry, _PAGE_ACCESSED);
        if(cause == EXCC_STORE_PAGE_FAULT){
            set_attribute(entry, _PAGE_DIRTY);
        }
    }
    else if(get_attribute(*entry, _PAGE_SOFT)){
        /* the page lives on the disk, bring it back into memory */
        int slot = get_pfn(*entry);
        ptr_t pa = alloc_user_page(0, entry);
        sbi_sd_read((unsigned int)pa, SECTORS_PER_PAGE,
                    SWAP_BEGIN + slot * SECTORS_PER_PAGE);
        disk_page[slot].valid = 0;
        set_leaf_page(entry, pa);
    }
    else{
        /* the first touch of the page: it starts out empty */
        ptr_t pa = alloc_user_page(0, entry);
        memset((void*)pa2kva(pa), 0, PAGE_SIZE);
        set_leaf_page(entry, pa);
    }

    local_flush_tlb_page(va);
    enable_preempt();
}

