/* prepare a kernel stack that looks like a task trapped into the kernel */
static void init_exec_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
                                pcb_t *new_pcb, int argc, uintptr_t argv)
{
    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
    new_pcb->kernel_sp -= sizeof(regs_context_t);

    /* initialization registers: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
    pt_regs->regs[1] = (reg_t)entry_point;       //ra
    pt_regs->regs[2] = (reg_t)user_stack;        //sp
    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
    pt_regs->regs[10] = (reg_t)argc;             //a0, argc of main()
    pt_regs->regs[11] = (reg_t)argv;             //a1, argv of main()
    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
    pt_regs->sepc = (reg_t)entry_point;
    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
}

/*
 * Copy the arguments of a new process to the top of its own stack: they are
 * read from the address space of the caller, which is still the one we run in.
 * `argc` is capped to what fits, and the user address of the `argv` array of
 * the new process is returned.
 */
static uintptr_t init_user_args(pcb_t *new_pcb, int *argc, char *argv[])
{
    uintptr_t pgdir = (uintptr_t)new_pcb->pgdir;
    uintptr_t arg_va[MAX_EXEC_ARGC];
    uintptr_t sp = USER_STACK_ADDR;
    int copied = 0;

    if (*argc > MAX_EXEC_ARGC) {
        *argc = MAX_EXEC_ARGC;
    }

    /* the strings themselves live at the very top of the stack */
    enable_sum();
    for (int i = 0; i < *argc; i++) {
        int length = strlen(argv[i]) + 1;
        if (copied + length > MAX_EXEC_ARG_SIZE) {
            /* the rest of them does not fit into the first page of stack */
            *argc = i;
            break;
        }
        copied += length;
        sp -= length;
        memcpy((uint8_t *)alloc_page_helper(sp, pgdir), (uint8_t *)argv[i], length);
        arg_va[i] = sp;
    }
    disable_sum();

    /* then the argv array itself, NULL terminated as main() expects it */
    sp = ROUNDDOWN(sp, sizeof(uintptr_t)) - (*argc + 1) * sizeof(uintptr_t);
    for (int i = 0; i < *argc; i++) {
        *(uintptr_t *)alloc_page_helper(sp + i * sizeof(uintptr_t), pgdir) = arg_va[i];
    }
    *(uintptr_t *)alloc_page_helper(sp + *argc * sizeof(uintptr_t), pgdir) = 0;

    /* the stack pointer of a RISC-V frame is 16 byte aligned */
    new_pcb->user_sp = ROUNDDOWN(sp, 16);
    return sp;
}

pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    disable_preempt();

    /* the name of the program is a string in the caller's address space */
    enable_sum();
    char *binary;
    int length;
    int found = get_elf_file(file_name, (unsigned char **)&binary, &length);
    disable_sum();
    if (!found) {
        enable_preempt();
        return -1;
    }

    /* find a free slot in the process table */
    pcb_t *new_pcb = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            new_pcb = &pcb[i];
            break;
        }
    }
    if (new_pcb == NULL) {
        enable_preempt();
        return 0;
    }

    if (free_page_num() < EXEC_PAGE_NUM) {
        enable_preempt();
        return -2;
    }

    /* the kernel stack is pinned: it must not be swapped out under us */
    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_sp = USER_STACK_ADDR;
    new_pcb->user_stack_base = USER_STACK_ADDR;
    new_pcb->preempt_count = 0;
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = USER_PROCESS;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = current_running[cpu_id]->priority;
    new_pcb->ready_tick = get_ticks();
    /* CPU affinity is inherited from the parent */
    new_pcb->mask = current_running[cpu_id]->mask;
    new_pcb->cursor_x = 1;
    new_pcb->cursor_y = 1;
    new_pcb->timer.list.prev = NULL;
    new_pcb->timer.list.next = NULL;
    init_list_head(&new_pcb->wait_list);

    /* a fresh address space, with the program and its arguments in it */
    new_pcb->pgdir = init_page_table();
    uintptr_t entry_point = load_elf((unsigned char *)binary, length,
                                     (uintptr_t)new_pcb->pgdir, alloc_page_helper);
    if (entry_point == 0) {
        /* the payload is not an ELF image after all */
        free_process_user_page(new_pcb->pgdir);
        free_user_page(kva2pa(new_pcb->kernel_stack_base - PAGE_SIZE));
        new_pcb->pgdir = (PTE *)PGDIR_PA;
        new_pcb->pid = -1;
        enable_preempt();
        return -1;
    }
    uintptr_t argv_base = init_user_args(new_pcb, &argc, argv);

    init_exec_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry_point,
                        new_pcb, argc, argv_base);
    list_add_tail(&new_pcb->list, &ready_queue);

    enable_preempt();
    return new_pcb->pid;
}

void do_exit()
{
    disable_preempt();

    pcb_t *dead = current_running[cpu_id];
    release_resources(dead);
    retire_pcb(dead);

    /* the CPU is free now, and this task will never be picked again */
    scheduler();

    enable_preempt();
}

