/*
 * Pick the ready task with the highest dynamic priority that is allowed to
 * run on this core. The dynamic priority is the static priority plus one
 * point per scheduling round spent waiting, so a low priority task cannot
 * be starved forever by a high priority one.
 */
list_node_t* max_priority_node(void)
{
    uint64_t now = get_ticks();
    uint64_t aging_unit = (timer_interval == 0) ? 1 : timer_interval;
    list_node_t *max_node = NULL;
    uint64_t max_priority = 0;

    for (list_node_t *p = ready_queue.next; p != &ready_queue; p = p->next) {
        pcb_t *task = list_entry(p, pcb_t, list);

        /* honour the CPU affinity mask */
        if (((task->mask >> cpu_id) & 1) == 0) {
            continue;
        }

        uint64_t waited = (now > task->ready_tick) ? (now - task->ready_tick) : 0;
        uint64_t dynamic_priority = (uint64_t)task->priority + waited / aging_unit;

        if (max_node == NULL || dynamic_priority > max_priority) {
            max_priority = dynamic_priority;
            max_node = p;
        }
    }

    return max_node;
}

