179	                         (get_attribute(entry, _PAGE_DIRTY) ? 1 : 0);
180	        if(page_class < victim_class){
181	            victim_class = page_class;
182	            victim = i;
183	        }
184	        clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
185	    }
186	
187	    if(victim < 0){
188	        /* everything left is pinned, there is nothing we may take away */
189	        return 0;
190	    }
191	
192	    flush_tlb_all_cores();
193	    return num2pa(victim);
194	}
