196	void write_to_sd(ptr_t pa)
197	{
198	    int slot;
199	    for(slot = 0; slot < DISK_PAGE_NUM; slot++){
200	        if(disk_page[slot].valid == 0){
201	            break;
202	        }
203	    }
204	    assert(slot != DISK_PAGE_NUM);
205	    disk_page[slot].valid = 1;
206	
207	    /* the SBI runs in machine mode, so it wants the physical address */
208	    sbi_sd_write((unsigned int)pa, SECTORS_PER_PAGE,
209	                 SWAP_BEGIN + slot * SECTORS_PER_PAGE);
210	
211	    /*
212	     * The owner has to fault the next time it touches the page, so its entry
213	     * keeps the swap slot instead of a frame number and is marked as
214	     * "invalid, but known to the kernel" with the software bit.
215	     */
216	    PTE *entry = user_page[pa2num(pa)].pgtable;
217	    if(entry != NULL){
218	        set_pfn(entry, slot);
219	        clear_attribute(entry, _PAGE_PRESENT | _PAGE_ACCESSED | _PAGE_DIRTY);
220	        set_attribute(entry, _PAGE_SOFT);
221	    }
222	
223	    free_user_page(pa);
224	    flush_tlb_all_cores();
225	}
