103	/* the last level entry of `va`, or NULL when the walk hits a hole */
104	static PTE *lookup(uintptr_t va, PTE *pgdir)
105	{
106	    PTE *table = (PTE *)pa2kva((uintptr_t)pgdir);
107	    int vpn[2] = {(int)((va >> VPN2_SHIFT) & VPN_MASK),
108	                  (int)((va >> VPN1_SHIFT) & VPN_MASK)};
109	
110	    for (int level = 0; level < 2; level++) {
111	        if (!get_attribute(table[vpn[level]], _PAGE_PRESENT)) return NULL;
112	        table = (PTE *)pa2kva(get_pa(table[vpn[level]]));
113	    }
114	    return &table[(va >> VPN0_SHIFT) & VPN_MASK];
115	}
