123	static void test_init_page_table(void)
124	{
125	    reset_mm();
126	    unsigned long free_before = free_page_num();
127	
128	    PTE *pgdir = init_page_table();
129	    CHECK(pgdir != NULL);
130	    CHECK((uintptr_t)pgdir >= FREE_PGDIR_ADDR && (uintptr_t)pgdir < MEM_END);
131	
132	    /* the kernel half is shared with the kernel page table, the user half is not */
133	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
134	    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
135	    CHECK(pgdir_kva[0x101] == kernel_pgdir[0x101]);
136	    CHECK(pgdir_kva[0x100] == 0);
137	    CHECK(pgdir_kva[0x1ff] == kernel_pgdir[0x1ff]);
138	
139	    /* the code of the program and one page of stack are mapped and zeroed */
140	    uintptr_t code[] = {0x10000, 0x11000, 0x12000, USER_STACK_ADDR - PAGE_SIZE};
141	    for (int i = 0; i < 4; i++) {
142	        PTE *entry = lookup(code[i], pgdir);
143	        CHECK(entry != NULL && get_attribute(*entry, _PAGE_PRESENT));
144	        CHECK(get_attribute(*entry, _PAGE_USER));
145	        CHECK(get_attribute(*entry, _PAGE_READ));
146	        CHECK(get_attribute(*entry, _PAGE_WRITE));
147	        CHECK(get_attribute(*entry, _PAGE_EXEC));
148	        CHECK(is_user_page(get_pa(*entry)));
149	        /* the page has to be reachable the way the ELF loader reaches it */
150	        uint64_t *page = (uint64_t *)get_kva_of(code[i], (uintptr_t)pgdir);
151	        CHECK(page[0] == 0 && page[100] == 0);
152	        page[0] = 0x1234;
153	        CHECK(*(uint64_t *)pa2kva(get_pa(*entry)) == 0x1234);
154	    }
155	
156	    /* every mapping is backed by a page of its own */
157	    for (int i = 0; i < 4; i++) {
158	        for (int j = i + 1; j < 4; j++) {
159	            CHECK(get_pa(*lookup(code[i], pgdir)) != get_pa(*lookup(code[j], pgdir)));
160	        }
161	    }
162	
163	    /* the share region stays free, shm_page_get() needs the room */
164	    CHECK(*lookup(0x1000, pgdir) == 0);
165	    CHECK(*lookup(0x8000, pgdir) == 0);
166	
167	    CHECK(free_page_num() == free_before - 6);
168	
169	    /* and everything comes back */
170	    test_pcb.pgdir = pgdir;
171	    free_process_user_page(pgdir);
172	    CHECK(free_page_num() == free_before);
173	    for (int i = 0; i < PGDIR_PAGE_NUM; i++) {
174	        CHECK(pgdir_page[i].valid == 0);
175	    }
176	}
