178	static void test_demand_paging(void)
179	{
180	    reset_mm();
181	    PTE *pgdir = init_page_table();
182	    test_pcb.pgdir = pgdir;
183	    unsigned long free_before = free_page_num();
184	
185	    /* a fresh address gets an empty page of its own */
186	    uintptr_t va = 0x20000000;
187	    CHECK(lookup(va, pgdir) == NULL);
188	    handle_page_fault(NULL, va + 0x40, EXCC_STORE_PAGE_FAULT);
189	    PTE *entry = lookup(va, pgdir);
190	    CHECK(entry != NULL && get_attribute(*entry, _PAGE_PRESENT));
191	    CHECK(get_attribute(*entry, _PAGE_USER) && get_attribute(*entry, _PAGE_WRITE));
192	    CHECK(free_page_num() == free_before - 1);
193	    uint64_t *page = (uint64_t *)get_kva_of(va, (uintptr_t)pgdir);
194	    CHECK(page[0] == 0);
195	    page[0] = 0xcafe;
196	
197	    /* faulting again only sets the bits the hardware may leave to us */
198	    handle_page_fault(NULL, va + 0x40, EXCC_STORE_PAGE_FAULT);
199	    CHECK(free_page_num() == free_before - 1);
200	    CHECK(get_attribute(*entry, _PAGE_ACCESSED) && get_attribute(*entry, _PAGE_DIRTY));
201	    CHECK(page[0] == 0xcafe);
202	    CHECK(get_pa(*entry) == kva2pa((uintptr_t)page));
203	
204	    /* a load fault does not claim the page was written to */
205	    uintptr_t va2 = 0x20001000;
206	    handle_page_fault(NULL, va2, EXCC_LOAD_PAGE_FAULT);
207	    PTE *entry2 = lookup(va2, pgdir);
208	    handle_page_fault(NULL, va2, EXCC_LOAD_PAGE_FAULT);
209	    CHECK(get_attribute(*entry2, _PAGE_ACCESSED));
210	    CHECK(!get_attribute(*entry2, _PAGE_DIRTY));
211	
212	    /* the kernel half of the address space is not demand paged */
213	    CHECK(fatal_faults == 0);
214	    handle_page_fault(NULL, 0xffffffc051000000lu, EXCC_STORE_PAGE_FAULT);
215	    CHECK(fatal_faults == 1);
216	
217	    free_process_user_page(pgdir);
218	}
