220	static void test_swap(void)
221	{
222	    reset_mm();
223	    PTE *pgdir = init_page_table();
224	    test_pcb.pgdir = pgdir;
225	
226	    /* the pages of the program itself must not be taken away from it */
227	    for (int i = 0; i < USER_PAGE_NUM; i++) {
228	        if (user_page[i].valid) user_page[i].pin = 1;
229	    }
230	    /* leave room for two pages only, so the third one has to evict somebody */
231	    int spare = 0;
232	    for (int i = 0; i < USER_PAGE_NUM; i++) {
233	        if (user_page[i].valid) continue;
234	        if (spare < 2) {
235	            spare++;
236	            continue;
237	        }
238	        user_page[i].valid = 1;
239	        user_page[i].pin = 1;
240	    }
241	    CHECK(free_page_num() == 2);
242	
243	    uintptr_t va1 = 0x30000000, va2 = 0x30001000, va3 = 0x30002000;
244	    handle_page_fault(NULL, va1, EXCC_STORE_PAGE_FAULT);
245	    PTE *entry1 = lookup(va1, pgdir);
246	    uintptr_t pa1 = get_pa(*entry1);
247	    uint64_t *page1 = (uint64_t *)pa2kva(pa1);
248	    for (int i = 0; i < 512; i++) page1[i] = 0xa5a50000lu + i;
249	
250	    handle_page_fault(NULL, va2, EXCC_STORE_PAGE_FAULT);
251	    CHECK(free_page_num() == 0);
252	
253	    /* no page left: the next fault has to write one out to the disk */
254	    handle_page_fault(NULL, va3, EXCC_STORE_PAGE_FAULT);
255	    PTE *entry3 = lookup(va3, pgdir);
256	    CHECK(get_attribute(*entry3, _PAGE_PRESENT));
257	    CHECK(!get_attribute(*entry1, _PAGE_PRESENT));
258	    CHECK(get_attribute(*entry1, _PAGE_SOFT));
259	    CHECK(get_pfn(*entry1) == 0);
260	    CHECK(disk_page[0].valid == 1);
261	    CHECK(get_pa(*entry3) == pa1); /* the freed frame is the one reused */
262	
263	    /* the swapped out page is on the disk, byte for byte */
264	    uint64_t *saved = (uint64_t *)host_disk[SWAP_BEGIN];
265	    CHECK(saved[0] == 0xa5a50000lu);
266	    CHECK(saved[511] == 0xa5a50000lu + 511);
267	
268	    /* touching it again brings it back, into whatever frame is free then */
269	    for (int i = 0; i < 512; i++) page1[i] = 0;   /* scribble over the frame */
270	    for (int i = 0; i < USER_PAGE_NUM; i++) {     /* make room for the swap in */
271	        if (user_page[i].valid && user_page[i].pgtable == NULL) {
272	            user_page[i].valid = 0;
273	            user_page[i].pin = 0;
274	            break;
275	        }
276	    }
277	    handle_page_fault(NULL, va1 + 8, EXCC_LOAD_PAGE_FAULT);
278	    CHECK(get_attribute(*entry1, _PAGE_PRESENT));
279	    CHECK(!get_attribute(*entry1, _PAGE_SOFT));
280	    CHECK(disk_page[0].valid == 0);
281	    uint64_t *restored = (uint64_t *)get_kva_of(va1, (uintptr_t)pgdir);
282	    CHECK(restored[0] == 0xa5a50000lu);
283	    CHECK(restored[511] == 0xa5a50000lu + 511);
284	
285	    /* a pinned page is never chosen as a victim */
286	    reset_mm();
287	    pgdir = init_page_table();
288	    test_pcb.pgdir = pgdir;
289	    handle_page_fault(NULL, 0x40000000, EXCC_STORE_PAGE_FAULT);
290	    PTE *pinned = lookup(0x40000000, pgdir);
291	    user_page[pa2num(get_pa(*pinned))].pin = 1;
292	    for (int i = 0; i < USER_PAGE_NUM; i++) {
293	        if (user_page[i].pgtable == NULL) user_page[i].pin = 1;
294	    }
295	    ptr_t victim = selete_page();
296	    CHECK(victim != 0);
297	    CHECK(victim != get_pa(*pinned));
298	    CHECK(user_page[pa2num(victim)].pin == 0);
299	
300	    /* nothing but pinned pages: there is no victim to be had */
301	    for (int i = 0; i < USER_PAGE_NUM; i++) {
302	        if (user_page[i].valid) user_page[i].pin = 1;
303	    }
304	    CHECK(selete_page() == 0);
305	}
