307	static void test_nru_order(void)
308	{
309	    reset_mm();
310	    PTE *pgdir = init_page_table();
311	    test_pcb.pgdir = pgdir;
312	
313	    /* three pages: one untouched, one read, one written */
314	    uintptr_t va[3] = {0x50000000, 0x50001000, 0x50002000};
315	    for (int i = 0; i < 3; i++) {
316	        handle_page_fault(NULL, va[i], EXCC_STORE_PAGE_FAULT);
317	    }
318	    for (int i = 0; i < USER_PAGE_NUM; i++) {
319	        /* only the three pages above may be evicted */
320	        if (user_page[i].valid && user_page[i].pgtable != NULL) {
321	            PTE *entry = user_page[i].pgtable;
322	            int keep = 0;
323	            for (int j = 0; j < 3; j++) {
324	                if (entry == lookup(va[j], pgdir)) keep = 1;
325	            }
326	            if (!keep) user_page[i].pin = 1;
327	        }
328	    }
329	    set_attribute(lookup(va[0], pgdir), _PAGE_ACCESSED | _PAGE_DIRTY);
330	    set_attribute(lookup(va[1], pgdir), _PAGE_ACCESSED);
331	    /* va[2] has been neither accessed nor written: it is the cheapest victim */
332	    CHECK(selete_page() == get_pa(*lookup(va[2], pgdir)));
333	    /* the sweep clears the reference bits it walked over */
334	    CHECK(!get_attribute(*lookup(va[0], pgdir), _PAGE_ACCESSED));
335	    CHECK(get_attribute(*lookup(va[0], pgdir), _PAGE_DIRTY));
336	    CHECK(!get_attribute(*lookup(va[1], pgdir), _PAGE_ACCESSED));
337	
338	    /* with the reference bits gone, the dirty one is the one to keep longest */
339	    ptr_t next = selete_page();
340	    CHECK(next == get_pa(*lookup(va[1], pgdir)) || next == get_pa(*lookup(va[2], pgdir)));
341	    CHECK(next != get_pa(*lookup(va[0], pgdir)));
342	}
