344	static void test_shm(void)
345	{
346	    reset_mm();
347	    PTE *pgdir_a = init_page_table();
348	    PTE *pgdir_b = init_page_table();
349	    unsigned long free_before = free_page_num();
350	
351	    /* the first user of a key brings the page into being */
352	    test_pcb.pgdir = pgdir_a;
353	    uintptr_t va_a = shm_page_get(42);
354	    CHECK(va_a >= 0x1000 && va_a < 0x10000);
355	    CHECK(free_page_num() == free_before - 1);
356	    int key_index = -1;
357	    for (int i = 0; i < SHM_PAGE_NUM; i++) {
358	        if (shm_page[i].count > 0) {
359	            CHECK(key_index == -1);
360	            key_index = i;
361	        }
362	    }
363	    CHECK(key_index >= 0 && shm_page[key_index].count == 1);
364	    CHECK(user_page[pa2num(shm_page[key_index].pa)].pin == 1);
365	
366	    uint64_t *shared_a = (uint64_t *)get_kva_of(va_a, (uintptr_t)pgdir_a);
367	    CHECK(shared_a[0] == 0);
368	    shared_a[0] = 0xdeadbeef;
369	
370	    /* the second process sees the very same page */
371	    test_pcb.pgdir = pgdir_b;
372	    uintptr_t va_b = shm_page_get(42);
373	    CHECK(va_b >= 0x1000 && va_b < 0x10000);
374	    CHECK(shm_page[key_index].count == 2);
375	    CHECK(free_page_num() == free_before - 1);
376	    uint64_t *shared_b = (uint64_t *)get_kva_of(va_b, (uintptr_t)pgdir_b);
377	    CHECK(shared_b == shared_a);
378	    CHECK(shared_b[0] == 0xdeadbeef);
379	
380	    /* another key is another page */
381	    uintptr_t other = shm_page_get(43);
382	    CHECK(other != va_b);
383	    CHECK(get_pa(*lookup(other, pgdir_b)) != shm_page[key_index].pa);
384	    CHECK(free_page_num() == free_before - 2);
385	    shm_page_dt(other);
386	    CHECK(free_page_num() == free_before - 1);
387	
388	    /*
389	     * After detaching, touching the address gives the process a private page,
390	     * and attaching again has to find another address.
391	     */
392	    shm_page_dt(va_b);
393	    CHECK(shm_page[key_index].count == 1);
394	    CHECK(*lookup(va_b, pgdir_b) == 0);
395	    handle_page_fault(NULL, va_b, EXCC_STORE_PAGE_FAULT);
396	    CHECK(*(uint64_t *)get_kva_of(va_b, (uintptr_t)pgdir_b) == 0);
397	    uintptr_t va_b2 = shm_page_get(42);
398	    CHECK(va_b2 != va_b);
399	    CHECK(shm_page[key_index].count == 2);
400	    CHECK(*(uint64_t *)get_kva_of(va_b2, (uintptr_t)pgdir_b) == 0xdeadbeef);
401	
402	    /* the shared page outlives the process which detaches last from it */
403	    free_process_user_page(pgdir_b);
404	    CHECK(shm_page[key_index].count == 1);
405	    CHECK(user_page[pa2num(shm_page[key_index].pa)].valid == 1);
406	    free_process_user_page(pgdir_a);
407	    CHECK(shm_page[key_index].count == 0);
408	    CHECK(free_page_num() == free_before + 12);  /* both address spaces are gone */
409	    for (int i = 0; i < PGDIR_PAGE_NUM; i++) {
410	        CHECK(pgdir_page[i].valid == 0);
411	    }
412	}
