/*
 * Host-side unit test for the Project 4 memory manager: SV39 page table
 * construction, demand paging, swapping to the SD card, shared pages and the
 * teardown of an address space.
 *
 * kernel/mm/mm.c is compiled for the host against the shims in hostshim/:
 * physical memory is a plain buffer, the SD card is the array below and the
 * privileged instructions are no-ops.
 */
#include <os/mm.h>
#include <os/sched.h>
#include <os/irq.h>
#include <pgtable.h>

/* --- the simulated machine --- */
unsigned char *host_phys_mem;
unsigned long host_satp;

#define DISK_SECTORS (SWAP_BEGIN + DISK_PAGE_NUM * (PAGE_SIZE / 512))
static unsigned char host_disk[DISK_SECTORS][512];

uintptr_t sbi_sd_write(unsigned int mem_address, unsigned int num_of_blocks,
                       unsigned int block_id)
{
    memcpy(host_disk[block_id], (uint8_t *)pa2kva(mem_address), num_of_blocks * 512);
    return 0;
}

uintptr_t sbi_sd_read(unsigned int mem_address, unsigned int num_of_blocks,
                      unsigned int block_id)
{
    memcpy((uint8_t *)pa2kva(mem_address), host_disk[block_id], num_of_blocks * 512);
    return 0;
}

/* --- stubs for the rest of the kernel --- */
int cpu_id;
pcb_t *volatile current_running[NR_CPUS];
pcb_t *volatile current_cpu_running;

int printk(const char *fmt, ...) { (void)fmt; return 0; }

int preempt_depth;
void disable_preempt(void) { preempt_depth++; }
void enable_preempt(void) { preempt_depth--; }

static int fatal_faults;
void handle_other(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    (void)regs; (void)stval; (void)cause;
    fatal_faults++;
}

/* --- tiny test harness --- */
extern int host_printf(const char *fmt, ...);
extern void *host_calloc(unsigned long n, unsigned long size);
static int failures;

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            failures++;                                                 \
            host_printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        }                                                               \
    } while (0)

/* the frame bookkeeping helpers of mm.c, they have no header of their own */
extern int pa2num(uintptr_t pa);
extern ptr_t num2pa(int num);

static pcb_t test_pcb;

static void reset_mm(void)
{
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        user_page[i].valid = 0;
        user_page[i].pin = 0;
        user_page[i].pgtable = NULL;
    }
    for (int i = 0; i < PGDIR_PAGE_NUM; i++) {
        pgdir_page[i].valid = 0;
    }
    for (int i = 0; i < DISK_PAGE_NUM; i++) {
        disk_page[i].valid = 0;
    }
    for (int i = 0; i < SHM_PAGE_NUM; i++) {
        shm_page[i].count = 0;
        shm_page[i].pa = 0;
    }
    kernel_memCurr = KERNEL_MEM_BEGIN;

    /* the kernel page table the address spaces inherit their upper half from */
    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    clear_pgdir(kernel_pgdir);
    set_pfn(&kernel_pgdir[0x101], (PGDIR_PA + PAGE_SIZE) >> NORMAL_PAGE_SHIFT);
    set_attribute(&kernel_pgdir[0x101], _PAGE_PRESENT);

    current_running[0] = &test_pcb;
    current_running[1] = &test_pcb;
    fatal_faults = 0;
}

/* the last level entry of `va`, or NULL when the walk hits a hole */
static PTE *lookup(uintptr_t va, PTE *pgdir)
{
    PTE *table = (PTE *)pa2kva((uintptr_t)pgdir);
    int vpn[2] = {(int)((va >> VPN2_SHIFT) & VPN_MASK),
                  (int)((va >> VPN1_SHIFT) & VPN_MASK)};

    for (int level = 0; level < 2; level++) {
        if (!get_attribute(table[vpn[level]], _PAGE_PRESENT)) return NULL;
        table = (PTE *)pa2kva(get_pa(table[vpn[level]]));
    }
    return &table[(va >> VPN0_SHIFT) & VPN_MASK];
}

static int is_user_page(uintptr_t pa)
{
    return pa >= USER_MEM_BEGIN && pa < USER_MEM_END &&
           user_page[pa2num(pa)].valid;
}

static void test_init_page_table(void)
{
    reset_mm();
    unsigned long free_before = free_page_num();

    PTE *pgdir = init_page_table();
    CHECK(pgdir != NULL);
    CHECK((uintptr_t)pgdir >= FREE_PGDIR_ADDR && (uintptr_t)pgdir < MEM_END);

    /* the kernel half is shared with the kernel page table, the user half is not */
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    CHECK(pgdir_kva[0x101] == kernel_pgdir[0x101]);
    CHECK(pgdir_kva[0x100] == 0);
    CHECK(pgdir_kva[0x1ff] == kernel_pgdir[0x1ff]);

    /* the code of the program and one page of stack are mapped and zeroed */
    uintptr_t code[] = {0x10000, 0x11000, 0x12000, USER_STACK_ADDR - PAGE_SIZE};
    for (int i = 0; i < 4; i++) {
        PTE *entry = lookup(code[i], pgdir);
        CHECK(entry != NULL && get_attribute(*entry, _PAGE_PRESENT));
        CHECK(get_attribute(*entry, _PAGE_USER));
        CHECK(get_attribute(*entry, _PAGE_READ));
        CHECK(get_attribute(*entry, _PAGE_WRITE));
        CHECK(get_attribute(*entry, _PAGE_EXEC));
        CHECK(is_user_page(get_pa(*entry)));
        /* the page has to be reachable the way the ELF loader reaches it */
        uint64_t *page = (uint64_t *)get_kva_of(code[i], (uintptr_t)pgdir);
        CHECK(page[0] == 0 && page[100] == 0);
        page[0] = 0x1234;
        CHECK(*(uint64_t *)pa2kva(get_pa(*entry)) == 0x1234);
    }

    /* every mapping is backed by a page of its own */
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            CHECK(get_pa(*lookup(code[i], pgdir)) != get_pa(*lookup(code[j], pgdir)));
        }
    }

    /* the share region stays free, shm_page_get() needs the room */
    CHECK(*lookup(0x1000, pgdir) == 0);
    CHECK(*lookup(0x8000, pgdir) == 0);

    CHECK(free_page_num() == free_before - 6);

    /* and everything comes back */
    test_pcb.pgdir = pgdir;
    free_process_user_page(pgdir);
    CHECK(free_page_num() == free_before);
    for (int i = 0; i < PGDIR_PAGE_NUM; i++) {
        CHECK(pgdir_page[i].valid == 0);
    }
}

static void test_demand_paging(void)
{
    reset_mm();
    PTE *pgdir = init_page_table();
    test_pcb.pgdir = pgdir;
    unsigned long free_before = free_page_num();

    /* a fresh address gets an empty page of its own */
    uintptr_t va = 0x20000000;
    CHECK(lookup(va, pgdir) == NULL);
    handle_page_fault(NULL, va + 0x40, EXCC_STORE_PAGE_FAULT);
    PTE *entry = lookup(va, pgdir);
    CHECK(entry != NULL && get_attribute(*entry, _PAGE_PRESENT));
    CHECK(get_attribute(*entry, _PAGE_USER) && get_attribute(*entry, _PAGE_WRITE));
    CHECK(free_page_num() == free_before - 1);
    uint64_t *page = (uint64_t *)get_kva_of(va, (uintptr_t)pgdir);
    CHECK(page[0] == 0);
    page[0] = 0xcafe;

    /* faulting again only sets the bits the hardware may leave to us */
    handle_page_fault(NULL, va + 0x40, EXCC_STORE_PAGE_FAULT);
    CHECK(free_page_num() == free_before - 1);
    CHECK(get_attribute(*entry, _PAGE_ACCESSED) && get_attribute(*entry, _PAGE_DIRTY));
    CHECK(page[0] == 0xcafe);
    CHECK(get_pa(*entry) == kva2pa((uintptr_t)page));

    /* a load fault does not claim the page was written to */
    uintptr_t va2 = 0x20001000;
    handle_page_fault(NULL, va2, EXCC_LOAD_PAGE_FAULT);
    PTE *entry2 = lookup(va2, pgdir);
    handle_page_fault(NULL, va2, EXCC_LOAD_PAGE_FAULT);
    CHECK(get_attribute(*entry2, _PAGE_ACCESSED));
    CHECK(!get_attribute(*entry2, _PAGE_DIRTY));

    /* the kernel half of the address space is not demand paged */
    CHECK(fatal_faults == 0);
    handle_page_fault(NULL, 0xffffffc051000000lu, EXCC_STORE_PAGE_FAULT);
    CHECK(fatal_faults == 1);

    free_process_user_page(pgdir);
}

static void test_swap(void)
{
    reset_mm();
    PTE *pgdir = init_page_table();
    test_pcb.pgdir = pgdir;

    /* the pages of the program itself must not be taken away from it */
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].valid) user_page[i].pin = 1;
    }
    /* leave room for two pages only, so the third one has to evict somebody */
    int spare = 0;
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].valid) continue;
        if (spare < 2) {
            spare++;
            continue;
        }
        user_page[i].valid = 1;
        user_page[i].pin = 1;
    }
    CHECK(free_page_num() == 2);

    uintptr_t va1 = 0x30000000, va2 = 0x30001000, va3 = 0x30002000;
    handle_page_fault(NULL, va1, EXCC_STORE_PAGE_FAULT);
    PTE *entry1 = lookup(va1, pgdir);
    uintptr_t pa1 = get_pa(*entry1);
    uint64_t *page1 = (uint64_t *)pa2kva(pa1);
    for (int i = 0; i < 512; i++) page1[i] = 0xa5a50000lu + i;

    handle_page_fault(NULL, va2, EXCC_STORE_PAGE_FAULT);
    CHECK(free_page_num() == 0);

    /* no page left: the next fault has to write one out to the disk */
    handle_page_fault(NULL, va3, EXCC_STORE_PAGE_FAULT);
    PTE *entry3 = lookup(va3, pgdir);
    CHECK(get_attribute(*entry3, _PAGE_PRESENT));
    CHECK(!get_attribute(*entry1, _PAGE_PRESENT));
    CHECK(get_attribute(*entry1, _PAGE_SOFT));
    CHECK(get_pfn(*entry1) == 0);
    CHECK(disk_page[0].valid == 1);
    CHECK(get_pa(*entry3) == pa1); /* the freed frame is the one reused */

    /* the swapped out page is on the disk, byte for byte */
    uint64_t *saved = (uint64_t *)host_disk[SWAP_BEGIN];
    CHECK(saved[0] == 0xa5a50000lu);
    CHECK(saved[511] == 0xa5a50000lu + 511);

    /* touching it again brings it back, into whatever frame is free then */
    for (int i = 0; i < 512; i++) page1[i] = 0;   /* scribble over the frame */
    for (int i = 0; i < USER_PAGE_NUM; i++) {     /* make room for the swap in */
        if (user_page[i].valid && user_page[i].pgtable == NULL) {
            user_page[i].valid = 0;
            user_page[i].pin = 0;
            break;
        }
    }
    handle_page_fault(NULL, va1 + 8, EXCC_LOAD_PAGE_FAULT);
    CHECK(get_attribute(*entry1, _PAGE_PRESENT));
    CHECK(!get_attribute(*entry1, _PAGE_SOFT));
    CHECK(disk_page[0].valid == 0);
    uint64_t *restored = (uint64_t *)get_kva_of(va1, (uintptr_t)pgdir);
    CHECK(restored[0] == 0xa5a50000lu);
    CHECK(restored[511] == 0xa5a50000lu + 511);

    /* a pinned page is never chosen as a victim */
    reset_mm();
    pgdir = init_page_table();
    test_pcb.pgdir = pgdir;
    handle_page_fault(NULL, 0x40000000, EXCC_STORE_PAGE_FAULT);
    PTE *pinned = lookup(0x40000000, pgdir);
    user_page[pa2num(get_pa(*pinned))].pin = 1;
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].pgtable == NULL) user_page[i].pin = 1;
    }
    ptr_t victim = selete_page();
    CHECK(victim != 0);
    CHECK(victim != get_pa(*pinned));
    CHECK(user_page[pa2num(victim)].pin == 0);

    /* nothing but pinned pages: there is no victim to be had */
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].valid) user_page[i].pin = 1;
    }
    CHECK(selete_page() == 0);
}

static void test_nru_order(void)
{
    reset_mm();
    PTE *pgdir = init_page_table();
    test_pcb.pgdir = pgdir;

    /* three pages: one untouched, one read, one written */
    uintptr_t va[3] = {0x50000000, 0x50001000, 0x50002000};
    for (int i = 0; i < 3; i++) {
        handle_page_fault(NULL, va[i], EXCC_STORE_PAGE_FAULT);
    }
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        /* only the three pages above may be evicted */
        if (user_page[i].valid && user_page[i].pgtable != NULL) {
            PTE *entry = user_page[i].pgtable;
            int keep = 0;
            for (int j = 0; j < 3; j++) {
                if (entry == lookup(va[j], pgdir)) keep = 1;
            }
            if (!keep) user_page[i].pin = 1;
        }
    }
    set_attribute(lookup(va[0], pgdir), _PAGE_ACCESSED | _PAGE_DIRTY);
    set_attribute(lookup(va[1], pgdir), _PAGE_ACCESSED);
    /* va[2] has been neither accessed nor written: it is the cheapest victim */
    CHECK(selete_page() == get_pa(*lookup(va[2], pgdir)));
    /* the sweep clears the reference bits it walked over */
    CHECK(!get_attribute(*lookup(va[0], pgdir), _PAGE_ACCESSED));
    CHECK(get_attribute(*lookup(va[0], pgdir), _PAGE_DIRTY));
    CHECK(!get_attribute(*lookup(va[1], pgdir), _PAGE_ACCESSED));

    /* with the reference bits gone, the dirty one is the one to keep longest */
    ptr_t next = selete_page();
    CHECK(next == get_pa(*lookup(va[1], pgdir)) || next == get_pa(*lookup(va[2], pgdir)));
    CHECK(next != get_pa(*lookup(va[0], pgdir)));
}

static void test_shm(void)
{
    reset_mm();
    PTE *pgdir_a = init_page_table();
    PTE *pgdir_b = init_page_table();
    unsigned long free_before = free_page_num();

    /* the first user of a key brings the page into being */
    test_pcb.pgdir = pgdir_a;
    uintptr_t va_a = shm_page_get(42);
    CHECK(va_a >= 0x1000 && va_a < 0x10000);
    CHECK(free_page_num() == free_before - 1);
    int key_index = -1;
    for (int i = 0; i < SHM_PAGE_NUM; i++) {
        if (shm_page[i].count > 0) {
            CHECK(key_index == -1);
            key_index = i;
        }
    }
    CHECK(key_index >= 0 && shm_page[key_index].count == 1);
    CHECK(user_page[pa2num(shm_page[key_index].pa)].pin == 1);

    uint64_t *shared_a = (uint64_t *)get_kva_of(va_a, (uintptr_t)pgdir_a);
    CHECK(shared_a[0] == 0);
    shared_a[0] = 0xdeadbeef;

    /* the second process sees the very same page */
    test_pcb.pgdir = pgdir_b;
    uintptr_t va_b = shm_page_get(42);
    CHECK(va_b >= 0x1000 && va_b < 0x10000);
    CHECK(shm_page[key_index].count == 2);
    CHECK(free_page_num() == free_before - 1);
    uint64_t *shared_b = (uint64_t *)get_kva_of(va_b, (uintptr_t)pgdir_b);
    CHECK(shared_b == shared_a);
    CHECK(shared_b[0] == 0xdeadbeef);

    /* another key is another page */
    uintptr_t other = shm_page_get(43);
    CHECK(other != va_b);
    CHECK(get_pa(*lookup(other, pgdir_b)) != shm_page[key_index].pa);
    CHECK(free_page_num() == free_before - 2);
    shm_page_dt(other);
    CHECK(free_page_num() == free_before - 1);

    /*
     * After detaching, touching the address gives the process a private page,
     * and attaching again has to find another address.
     */
    shm_page_dt(va_b);
    CHECK(shm_page[key_index].count == 1);
    CHECK(*lookup(va_b, pgdir_b) == 0);
    handle_page_fault(NULL, va_b, EXCC_STORE_PAGE_FAULT);
    CHECK(*(uint64_t *)get_kva_of(va_b, (uintptr_t)pgdir_b) == 0);
    uintptr_t va_b2 = shm_page_get(42);
    CHECK(va_b2 != va_b);
    CHECK(shm_page[key_index].count == 2);
    CHECK(*(uint64_t *)get_kva_of(va_b2, (uintptr_t)pgdir_b) == 0xdeadbeef);

    /* the shared page outlives the process which detaches last from it */
    free_process_user_page(pgdir_b);
    CHECK(shm_page[key_index].count == 1);
    CHECK(user_page[pa2num(shm_page[key_index].pa)].valid == 1);
    free_process_user_page(pgdir_a);
    CHECK(shm_page[key_index].count == 0);
    CHECK(free_page_num() == free_before + 12);  /* both address spaces are gone */
    for (int i = 0; i < PGDIR_PAGE_NUM; i++) {
        CHECK(pgdir_page[i].valid == 0);
    }
}

static void test_free_swapped_process(void)
{
    reset_mm();
    PTE *pgdir = init_page_table();
    test_pcb.pgdir = pgdir;

    /* a process with a page on the disk gives its swap slot back as well */
    handle_page_fault(NULL, 0x60000000, EXCC_STORE_PAGE_FAULT);
    PTE *entry = lookup(0x60000000, pgdir);
    write_to_sd(get_pa(*entry));
    CHECK(disk_page[0].valid == 1);
    CHECK(get_attribute(*entry, _PAGE_SOFT));

    free_process_user_page(pgdir);
    CHECK(disk_page[0].valid == 0);
    for (int i = 0; i < DISK_PAGE_NUM; i++) {
        CHECK(disk_page[i].valid == 0);
    }
}

int run_tests(void)
{
    host_phys_mem = (unsigned char *)host_calloc(HOST_PHYS_SIZE, 1);
    if (host_phys_mem == NULL) {
        host_printf("p4: cannot allocate the simulated physical memory\n");
        return 1;
    }

    test_init_page_table();
    test_demand_paging();
    test_swap();
    test_nru_order();
    test_shm();
    test_free_swapped_process();

    if (failures == 0) {
        host_printf("p4: all page table/demand paging/swap/shm checks passed\n");
    }
    return failures != 0;
}

