=== atomic.h ===
/*
 * Host stand-in for arch/riscv/include/atomic.h.
 *
 * The real header is RISC-V inline assembly; the host unit tests are
 * single-threaded so plain loads and stores are enough.
 */
#ifndef ATOMIC_H
#define ATOMIC_H

#include <type.h>

static inline uint32_t atomic_swap(uint32_t val, ptr_t mem_addr)
{
    uint32_t *p = (uint32_t *)mem_addr;
    uint32_t ret = *p;
    *p = val;
    return ret;
}

static inline uint64_t atomic_swap_d(uint64_t val, ptr_t mem_addr)
{
    uint64_t *p = (uint64_t *)mem_addr;
    uint64_t ret = *p;
    *p = val;
    return ret;
}

static inline int fetch_add(volatile void *obj, int arg)
{
    volatile uint32_t *p = (volatile uint32_t *)obj;
    uint32_t ret = *p;
    *p = ret + arg;
    return ret;
}

static inline uint32_t atomic_load(volatile uint32_t *obj)
{
    return *obj;
}

static inline uint32_t atomic_cmpxchg(uint32_t old_val, uint32_t new_val, ptr_t mem_addr)
{
    uint32_t *p = (uint32_t *)mem_addr;
    uint32_t ret = *p;
    if (ret == old_val) *p = new_val;
    return ret;
}

static inline uint64_t atomic_cmpxchg_d(uint64_t old_val, uint64_t new_val, ptr_t mem_addr)
{
    uint64_t *p = (uint64_t *)mem_addr;
    uint64_t ret = *p;
    if (ret == old_val) *p = new_val;
    return ret;
}

#endif /* ATOMIC_H */
=== pgtable.h ===
/*
 * Host stand-in for arch/riscv/include/pgtable.h.
 *
 * The bit layout, the entry accessors and the page table walk are the real
 * ones - that is what the tests are about - but the physical address space is
 * a plain host buffer and the privileged instructions are no-ops.
 */
#ifndef PGTABLE_H
#define PGTABLE_H

#include <type.h>
#include <sbi.h>
#include <os/string.h>

static inline void local_flush_tlb_all(void) {}
static inline void local_flush_tlb_page(unsigned long addr) { (void)addr; }
static inline void local_flush_icache_all(void) {}
static inline void flush_tlb_all(void) {}
static inline void flush_tlb_page_all(unsigned long addr) { (void)addr; }
static inline void flush_icache_all(void) {}

#define SATP_MODE_SV39 8
#define SATP_MODE_SV48 9
#define SATP_ASID_SHIFT 44lu
#define SATP_MODE_SHIFT 60lu

/* the page table the test suite pretends the hardware walks */
extern unsigned long host_satp;

static inline void set_satp(unsigned mode, unsigned asid, unsigned long ppn)
{
    host_satp = ((unsigned long)mode << SATP_MODE_SHIFT) |
                ((unsigned long)asid << SATP_ASID_SHIFT) | ppn;
}

#define PGDIR_PA 0x5e000000lu

#define NORMAL_PAGE_SHIFT 12lu
#define NORMAL_PAGE_SIZE (1lu << NORMAL_PAGE_SHIFT)
#define LARGE_PAGE_SHIFT 21lu
#define LARGE_PAGE_SIZE (1lu << LARGE_PAGE_SHIFT)

#define _PAGE_PRESENT (1 << 0)
#define _PAGE_READ (1 << 1)
#define _PAGE_WRITE (1 << 2)
#define _PAGE_EXEC (1 << 3)
#define _PAGE_USER (1 << 4)
#define _PAGE_GLOBAL (1 << 5)
#define _PAGE_ACCESSED (1 << 6)
#define _PAGE_DIRTY (1 << 7)
#define _PAGE_SOFT (1 << 8)
#define _PAGE_PFN_SHIFT 10lu

#define VA_MASK ((1lu << 39) - 1)
#define PFN_MASK ((1lu << 44) - 1)
#define ATTRIBUTE_MASK ((1lu << 9) - 1)
#define PAGE_OFFSET_MASK ((1lu << 12) - 1)

#define PPN_BITS 9lu
#define NUM_PTE_ENTRY (1 << PPN_BITS)
#define PPN_MASK ((1lu << PPN_BITS) - 1)
#define VPN_MASK ((1lu << PPN_BITS) - 1)

#define VPN2_SHIFT 30
#define VPN1_SHIFT 21
#define VPN0_SHIFT 12

/*
 * The simulated physical memory covers 0x5000_0000 ~ 0x6000_0000, the range
 * the board has. `host_phys_mem` is set up by the test before anything else
 * runs, and takes the place of the kernel's linear mapping.
 */
#define HOST_PHYS_BASE 0x50000000lu
#define HOST_PHYS_SIZE 0x10000000lu
extern unsigned char *host_phys_mem;

/* the real header has this as a constant, only its use as an offset matters */
#define KERNEL_MEM_OFFSET ((uintptr_t)host_phys_mem - HOST_PHYS_BASE)

typedef uint64_t PTE;

static inline void clear_pgdir(PTE* pgdir_addr)
{
    memset(pgdir_addr, 0, 4096);
}

static inline long get_pfn(PTE entry)
{
    return ((entry >> _PAGE_PFN_SHIFT) & PFN_MASK);
}
static inline void set_pfn(PTE *entry, uint64_t pfn)
{
    *entry = *entry & ATTRIBUTE_MASK;
    *entry = *entry | (pfn << _PAGE_PFN_SHIFT);
}
static inline uintptr_t get_pa(PTE entry)
{
    return (((entry >> _PAGE_PFN_SHIFT) & PFN_MASK) << NORMAL_PAGE_SHIFT);
}

