/*
 * Host stand-in for arch/riscv/include/atomic.h.
 *
 * The real header is RISC-V inline assembly; the host unit tests are
 * single-threaded so plain loads and stores are enough.
 */
#ifndef ATOMIC_H
#define ATOMIC_H

#include <type.h>

static inline uint32_t atomic_swap(uint32_t val, ptr_t mem_addr)
{
    uint32_t *p = (uint32_t *)mem_addr;
    uint32_t ret = *p;
    *p = val;
    return ret;
}

static inline uint64_t atomic_swap_d(uint64_t val, ptr_t mem_addr)
{
    uint64_t *p = (uint64_t *)mem_addr;
    uint64_t ret = *p;
    *p = val;
    return ret;
}

static inline int fetch_add(volatile void *obj, int arg)
{
    volatile uint32_t *p = (volatile uint32_t *)obj;
    uint32_t ret = *p;
    *p = ret + arg;
    return ret;
}

static inline uint32_t atomic_load(volatile uint32_t *obj)
{
    return *obj;
}

static inline uint32_t atomic_cmpxchg(uint32_t old_val, uint32_t new_val, ptr_t mem_addr)
{
    uint32_t *p = (uint32_t *)mem_addr;
    uint32_t ret = *p;
    if (ret == old_val) *p = new_val;
    return ret;
}

static inline uint64_t atomic_cmpxchg_d(uint64_t old_val, uint64_t new_val, ptr_t mem_addr)
{
    uint64_t *p = (uint64_t *)mem_addr;
    uint64_t ret = *p;
    if (ret == old_val) *p = new_val;
    return ret;
}

