/*
 * Host-side unit test for the Project 5 memory manager: SV39 page table
 * construction, demand paging, swapping to the SD card, shared pages and the
 * teardown of an address space.
 *
 * kernel/mm/mm.c is compiled for the host against the shims in hostshim/:
 * physical memory is a plain buffer, the SD card is the array below and the
 * privileged instructions are no-ops.
 */
#include <os/mm.h>
#include <os/sched.h>
#include <os/irq.h>

