int run_tests(void)
{
    host_phys_mem = (unsigned char *)host_calloc(HOST_PHYS_SIZE, 1);
    if (host_phys_mem == NULL) {
        host_printf("p5: cannot allocate the simulated physical memory\n");
        return 1;
    }

    test_init_page_table();
    test_demand_paging();
    test_swap();
    test_nru_order();
    test_shm();
    test_free_swapped_process();

    if (failures == 0) {
        host_printf("p5: all page table/demand paging/swap/shm checks passed\n");
    }
    return failures != 0;
}

