static void test_alloc_page_helper(void)
{
    reset_mm();
    PTE *pgdir = init_page_table();
    test_pcb.pgdir = pgdir;
    unsigned long free_before = free_page_num();

    /* a page which is already there is handed back as it is */
    uintptr_t mapped = 0x10000;
    PTE *entry = lookup(mapped, pgdir);
    CHECK(alloc_page_helper(mapped, (uintptr_t)pgdir) == pa2kva(get_pa(*entry)));
    /* the offset inside the page is kept, the ELF loader relies on it */
    CHECK(alloc_page_helper(mapped + 0x123, (uintptr_t)pgdir) ==
          pa2kva(get_pa(*entry)) + 0x123);
    CHECK(free_page_num() == free_before);

    /* an address which is not mapped yet gets an empty page of its own */
    uintptr_t fresh = 0x20000000;
    CHECK(lookup(fresh, pgdir) == NULL);
    uintptr_t kva = alloc_page_helper(fresh + 0x10, (uintptr_t)pgdir);
    entry = lookup(fresh, pgdir);
    CHECK(entry != NULL && get_attribute(*entry, _PAGE_PRESENT));
    CHECK(get_attribute(*entry, _PAGE_USER) && get_attribute(*entry, _PAGE_WRITE));
    CHECK(get_attribute(*entry, _PAGE_READ) && get_attribute(*entry, _PAGE_EXEC));
    CHECK(kva == pa2kva(get_pa(*entry)) + 0x10);
    CHECK(free_page_num() == free_before - 1);
    CHECK(*(uint64_t *)kva == 0);
    *(uint64_t *)kva = 0x5a5a;
    /* asking a second time does not move the page */
    CHECK(alloc_page_helper(fresh + 0x10, (uintptr_t)pgdir) == kva);
    CHECK(free_page_num() == free_before - 1);

    /* a page which has been swapped out is read back from the disk */
    uintptr_t pa = get_pa(*entry);
    write_to_sd(pa);
    CHECK(!get_attribute(*entry, _PAGE_PRESENT) && get_attribute(*entry, _PAGE_SOFT));
    CHECK(disk_page[0].valid == 1);
    kva = alloc_page_helper(fresh + 0x10, (uintptr_t)pgdir);
    CHECK(get_attribute(*entry, _PAGE_PRESENT) && !get_attribute(*entry, _PAGE_SOFT));
    CHECK(disk_page[0].valid == 0);
    CHECK(*(uint64_t *)kva == 0x5a5a);

    /* the loader walks a whole segment through it, page by page */
    for (uintptr_t va = 0x30000000; va < 0x30004000; va += PAGE_SIZE) {
        *(uint64_t *)alloc_page_helper(va, (uintptr_t)pgdir) = va;
    }
    for (uintptr_t va = 0x30000000; va < 0x30004000; va += PAGE_SIZE) {
        CHECK(*(uint64_t *)get_kva_of(va, (uintptr_t)pgdir) == va);
    }

    free_process_user_page(pgdir);
    CHECK(free_page_num() == free_before + 6);
}

int run_tests(void)
{
    host_phys_mem = (unsigned char *)host_calloc(HOST_PHYS_SIZE, 1);
    if (host_phys_mem == NULL) {
        host_printf("p5: cannot allocate the simulated physical memory\n");
        return 1;
    }

    test_init_page_table();
    test_alloc_page_helper();
    test_demand_paging();
    test_swap();
    test_nru_order();
    test_shm();
    test_free_swapped_process();

    if (failures == 0) {
        host_printf("p5: all page table/alloc_page_helper/swap/shm checks passed\n");
    }
    return failures != 0;
}

