static int queue_contains(list_head *head, list_node_t *node)
{
    for (list_node_t *p = head->next; p != head; p = p->next) {
        if (p == node) return 1;
    }
    return 0;
}

static void reset_kernel(void)
{
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        user_page[i].valid = 0;
        user_page[i].pin = 0;
        user_page[i].pgtable = NULL;
    }
    for (int i = 0; i < PGDIR_PAGE_NUM; i++) pgdir_page[i].valid = 0;
    for (int i = 0; i < DISK_PAGE_NUM; i++) disk_page[i].valid = 0;
    for (int i = 0; i < SHM_PAGE_NUM; i++) {
        shm_page[i].count = 0;
        shm_page[i].pa = 0;
    }

    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    clear_pgdir(kernel_pgdir);
    set_pfn(&kernel_pgdir[0x101], (PGDIR_PA + PAGE_SIZE) >> NORMAL_PAGE_SHIFT);
    set_attribute(&kernel_pgdir[0x101], _PAGE_PRESENT);

    init_list_head(&ready_queue);
    init_list_head(&sleep_queue);
    init_list_head(&timer_queue);
    init_system_binsem();

    for (int i = 0; i < NR_CPUS; i++) {
        kernel_pcb[i].pid = 0;
        kernel_pcb[i].type = KERNEL_PROCESS;
        kernel_pcb[i].status = TASK_RUNNING;
        kernel_pcb[i].priority = 0;
        kernel_pcb[i].mask = 1lu << i;
        kernel_pcb[i].cpu_id = i;
        kernel_pcb[i].preempt_count = 0;
        kernel_pcb[i].binsem_num = 0;
        kernel_pcb[i].pgdir = (PTE *)PGDIR_PA;
        kernel_pcb[i].kernel_sp = pa2kva(KERNEL_MEM_BEGIN + (i + 1) * PAGE_SIZE);
        kernel_pcb[i].user_sp = kernel_pcb[i].kernel_sp;
        kernel_pcb[i].cursor_x = 1;
        kernel_pcb[i].cursor_y = 1;
        init_list_head(&kernel_pcb[i].wait_list);
        kernel_pcb[i].timer.list.prev = NULL;
        kernel_pcb[i].timer.list.next = NULL;
    }

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        pcb[i].pid = -1;
        pcb[i].pgdir = NULL;
        pcb[i].binsem_num = 0;
        pcb[i].timer.list.prev = NULL;
        pcb[i].timer.list.next = NULL;
        init_list_head(&pcb[i].wait_list);
    }

