long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    if (num_packet <= 0) {
        return 0;
    }
    if (num_packet > RXBD_CNT) {
        num_packet = RXBD_CNT;
    }

    disable_preempt();

    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;

    /*
     * The packets are handed over through the kernel's own mapping of the
     * buffer - in interrupt mode the copy happens while any address space may
     * be the one loaded - so all of its pages have to exist before the DMA
     * engine starts.
     */
    for (uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE); va < addr + length;
         va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }
    uintptr_t length_end = (uintptr_t)frLength + num_packet * sizeof(size_t);
    for (uintptr_t va = ROUNDDOWN((uintptr_t)frLength, PAGE_SIZE);
         va < length_end; va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }

    _addr = alloc_page_helper(addr, pgdir);
    _num_packet = num_packet;
    _frLength = (size_t *)alloc_page_helper((uintptr_t)frLength, pgdir);

    /* hand the receive descriptors over to the DMA engine */
    if (!net_poll_mode) {
        recv_transaction = 1;
    }
    EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);

