long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    if (num_packet <= 0 || length == 0) {
        return 0;
    }
    if (num_packet > RXBD_CNT) {
        num_packet = RXBD_CNT;
    }

    disable_preempt();

    pcb_t *self = current_running[cpu_id];
    uintptr_t pgdir = (uintptr_t)self->pgdir;

    if (recv_owner == self) {
        /*
         * The transfer this task started in interrupt mode is over: the
         * handler has copied the packets and their lengths into the buffers
         * of the task already, all that is left is to report how much came in.
         */
        recv_owner = NULL;
        long received = 0;
        for (int i = 0; i < num_packet; i++) {
            received += rx_len[i];
        }
        enable_preempt();
        return received;
    }

    /*
     * The packets are handed over through the kernel's own mapping of the
     * buffer - in interrupt mode the copy happens while any address space may
     * be the one loaded - so all of its pages have to exist before the DMA
     * engine starts.
     */
    for (uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE); va < addr + length;
         va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }
    uintptr_t length_end = (uintptr_t)frLength + num_packet * sizeof(size_t);
    for (uintptr_t va = ROUNDDOWN((uintptr_t)frLength, PAGE_SIZE);
         va < length_end; va += PAGE_SIZE) {
        alloc_page_helper(va, pgdir);
    }

    if (net_poll_mode) {
        /* hand the receive descriptors over to the DMA engine and sit on it */
        EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);

        long received = 0;
        uintptr_t curr = addr;
        size_t room = length;
        for (int i = 0; i < num_packet; i++) {
            size_t copied = (rx_len[i] < room) ? rx_len[i] : room;
            copy_to_user_buffer(curr, (uint8_t *)&rx_buffers[i], copied, pgdir);
            *(size_t *)alloc_page_helper((uintptr_t)&frLength[i], pgdir) = rx_len[i];
            curr += copied;
            room -= copied;
            received += rx_len[i];
        }

        enable_preempt();
        return received;
    }

    /*
     * Interrupt mode: XEmacPsRecvHandler fills the buffers of the task and
     * wakes it up. Its result can only be reported once that has happened, so
     * the syscall is rewound and retried when the task runs again - the way
     * do_waitpid() waits for a child. The retry needs the buffer in a0 again,
     * hence the return value.
     */
    _addr = alloc_page_helper(addr, pgdir);
    _num_packet = num_packet;
    _frLength = (size_t *)alloc_page_helper((uintptr_t)frLength, pgdir);
    recv_owner = self;
    recv_transaction = 1;
    EmacPsRecv(&EmacPsInstance, rx_buffers, num_packet);

    ((regs_context_t *)self->kernel_sp)->sepc -= 4;
    do_block(&self->list, &net_recv_queue);
    scheduler();

    enable_preempt();
    return (long)addr;
}

