#include <net.h>
#include <os/string.h>
#include <screen.h>
#include <emacps/xemacps_example.h>
#include <emacps/xemacps.h>
#include <assert.h>
#include <os/sched.h>
#include <os/mm.h>
#include <os/irq.h>

EthernetFrame rx_buffers[RXBD_CNT];
EthernetFrame tx_buffer;
uint32_t rx_len[RXBD_CNT];

/*
 * The device comes up with its interrupts masked - EmacPsInit leaves them that
 * way - so until a task asks for interrupt mode the driver polls.
 */
int net_poll_mode = 1;

LIST_HEAD(net_recv_queue);
LIST_HEAD(net_send_queue);

uintptr_t rx_curr = 0, rx_tail = 0;
int recv_transaction = 0,  send_transaction = 0;

uintptr_t _addr;
int _num_packet;
size_t* _frLength;

/* the interrupts the driver lives on while it is running in interrupt mode */
#define NET_IRQ_MASK                                     \
    (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK | \
     (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK)

/*
 * A user buffer is contiguous in the address space of its owner, but the pages
 * behind it are not, so it is copied one page at a time. The pages are created
 * on the way: the buffer of a program usually is memory it never touched.
 */
static void copy_to_user_buffer(uintptr_t va, const uint8_t *src, size_t length,
                                uintptr_t pgdir)
{
    while (length > 0) {
        size_t chunk = PAGE_SIZE - (va & (PAGE_SIZE - 1));
        if (chunk > length) {
            chunk = length;
        }
        memcpy((uint8_t *)alloc_page_helper(va, pgdir), (uint8_t *)src, chunk);
        va += chunk;
        src += chunk;
        length -= chunk;
    }
}

static void copy_from_user_buffer(uint8_t *dest, uintptr_t va, size_t length,
                                  uintptr_t pgdir)
{
    while (length > 0) {
        size_t chunk = PAGE_SIZE - (va & (PAGE_SIZE - 1));
        if (chunk > length) {
            chunk = length;
        }
        memcpy(dest, (uint8_t *)alloc_page_helper(va, pgdir), chunk);
        va += chunk;
        dest += chunk;
        length -= chunk;
    }
}

