    CHECK(net_poll_mode == 1);

    do_net_irq_mode(1);
    CHECK(net_poll_mode == 0);
    /* the frame and error interrupts of both directions are turned on */
    uint32_t enabled = device_reg(XEMACPS_IER_OFFSET);
    CHECK(enabled & XEMACPS_IXR_FRAMERX_MASK);
    CHECK(enabled & XEMACPS_IXR_TXCOMPL_MASK);
    CHECK(enabled & XEMACPS_IXR_RX_ERR_MASK);
    CHECK(enabled & XEMACPS_IXR_TX_ERR_MASK);

    recv_transaction = 1;
    send_transaction = 1;
    do_net_irq_mode(0);
    CHECK(net_poll_mode == 1);
    uint32_t disabled = device_reg(XEMACPS_IDR_OFFSET);
    CHECK(disabled & XEMACPS_IXR_FRAMERX_MASK);
    CHECK(disabled & XEMACPS_IXR_TXCOMPL_MASK);
    /* nothing is going to be woken up any more */
    CHECK(recv_transaction == 0 && send_transaction == 0);
}

static void test_poll_recv(void)
{
    reset_driver();
    uintptr_t pgdir = (uintptr_t)test_pcb.pgdir;
    unsigned long free_before = free_page_num();

    /* a buffer the program has never touched: the driver has to map it */
    uintptr_t buffer = 0x20000000;
    uintptr_t lengths = 0x21000000;
    scripted_len[0] = 60;
    scripted_len[1] = 100;

    long ret = do_net_recv(buffer, 2 * sizeof(EthernetFrame), 2, (size_t *)lengths);
    CHECK(ret == 160);
    CHECK(recv_calls == 1 && recv_num_packet == 2);
    CHECK(wait_recv_calls == 1);
    CHECK(scheduler_calls == 0);            /* poll mode never blocks */
    CHECK(recv_transaction == 0);
    CHECK(free_page_num() < free_before);

    /* the packets are one after the other in the buffer of the program */
    unsigned char *user = (unsigned char *)get_kva_of(buffer, pgdir);
    for (int i = 0; i < 60; i++) CHECK(user[i] == packet_fill(0));
    for (int i = 60; i < 160; i++) CHECK(user[i] == packet_fill(1));
    size_t *user_len = (size_t *)get_kva_of(lengths, pgdir);
    CHECK(user_len[0] == 60 && user_len[1] == 100);

    /* a single packet which crosses a page boundary is copied page by page */
    reset_driver();
    pgdir = (uintptr_t)test_pcb.pgdir;
    buffer = 0x30000000 + PAGE_SIZE - 32;
    lengths = 0x31000000;
    scripted_len[0] = 1000;
    CHECK(do_net_recv(buffer, sizeof(EthernetFrame), 1, (size_t *)lengths) == 1000);
    for (int i = 0; i < 1000; i++) {
        unsigned char *byte = (unsigned char *)get_kva_of(buffer + i, pgdir);
        CHECK(*byte == packet_fill(0));
    }
    CHECK(*(size_t *)get_kva_of(lengths, pgdir) == 1000);

    /* nothing to receive is not an error */
    reset_driver();
    CHECK(do_net_recv(0x20000000, PAGE_SIZE, 0, (size_t *)0x21000000) == 0);
    CHECK(recv_calls == 0);
}

static void test_poll_send(void)
{
    reset_driver();
    uintptr_t pgdir = (uintptr_t)test_pcb.pgdir;

    /* a buffer of the program which crosses a page boundary */
    uintptr_t buffer = 0x40000000 + PAGE_SIZE - 40;
    for (int i = 0; i < 88; i++) {
        *(unsigned char *)alloc_page_helper(buffer + i, pgdir) = (unsigned char)i;
    }

    do_net_send(buffer, 88);
    CHECK(send_calls == 1);
    CHECK(send_length == 88);
    CHECK(wait_send_calls == 1);            /* poll mode waits for the frame */
    CHECK(scheduler_calls == 0);
    CHECK(send_transaction == 0);
    for (int i = 0; i < 88; i++) {
        CHECK(((unsigned char *)&tx_buffer)[i] == (unsigned char)i);
    }
}

static void test_interrupt_recv(void)
{
    reset_driver();
    uintptr_t pgdir = (uintptr_t)test_pcb.pgdir;
    do_net_irq_mode(1);

    uintptr_t buffer = 0x50000000;
    uintptr_t lengths = 0x51000000;
    scripted_len[0] = 200;
    scripted_len[1] = 300;

    long ret = do_net_recv(buffer, 2 * sizeof(EthernetFrame), 2, (size_t *)lengths);

    /* the transfer is handed to the device and the caller waits for the irq */
    CHECK(recv_calls == 1 && recv_num_packet == 2);
    CHECK(wait_recv_calls == 0);            /* nobody polls the descriptors */
    CHECK(recv_transaction == 1);
    CHECK(test_pcb.status == TASK_BLOCKED);
    CHECK(queue_contains(&net_recv_queue, &test_pcb.list));
    CHECK(scheduler_calls == 1);
    /* the syscall is retried when the handler wakes the task up */
    CHECK(test_regs.sepc == SYSCALL_SEPC - 4);
    CHECK(ret == (long)buffer);             /* a0 holds the buffer again */

    /* the handler reaches the buffers of the task through the kernel mapping */
    CHECK(_addr == get_kva_of(buffer, pgdir));
    CHECK(_num_packet == 2);
    CHECK((uintptr_t)_frLength == get_kva_of(lengths, pgdir));

    /* XEmacPsRecvHandler: copy the frames in, hand out the lengths, wake up */
    uintptr_t curr = _addr;
    for (int i = 0; i < _num_packet; i++) {
        rx_len[i] = scripted_len[i];
        memcpy((uint8_t *)curr, (uint8_t *)&rx_buffers[i], rx_len[i]);
        _frLength[i] = rx_len[i];
        curr += rx_len[i];
    }
    recv_transaction = 0;
    do_unblock(net_recv_queue.next);
    CHECK(test_pcb.status == TASK_READY);

    /* the retried syscall reports what came in, without starting over */
    test_pcb.status = TASK_RUNNING;
    ret = do_net_recv(buffer, 2 * sizeof(EthernetFrame), 2, (size_t *)lengths);
    CHECK(ret == 500);
    CHECK(recv_calls == 1);                 /* the device is not asked twice */
    CHECK(scheduler_calls == 1);            /* and the task does not block */
    CHECK(test_pcb.status == TASK_RUNNING);
    unsigned char *user = (unsigned char *)get_kva_of(buffer, pgdir);
    CHECK(user[0] == packet_fill(0) && user[199] == packet_fill(0));
    CHECK(user[200] == packet_fill(1));
    size_t *user_len = (size_t *)get_kva_of(lengths, pgdir);
    CHECK(user_len[0] == 200 && user_len[1] == 300);
}

static void test_interrupt_send(void)
{
    reset_driver();
    uintptr_t pgdir = (uintptr_t)test_pcb.pgdir;
    do_net_irq_mode(1);

    uintptr_t buffer = 0x60000000;
    for (int i = 0; i < 64; i++) {
        *(unsigned char *)alloc_page_helper(buffer + i, pgdir) = (unsigned char)(i + 1);
    }

    do_net_send(buffer, 64);
    CHECK(send_calls == 1 && send_length == 64);
    CHECK(wait_send_calls == 0);            /* the irq reports the frame is out */
    CHECK(send_transaction == 1);
    CHECK(test_pcb.status == TASK_BLOCKED);
    CHECK(queue_contains(&net_send_queue, &test_pcb.list));
    CHECK(scheduler_calls == 1);
    /* the frame is in the buffer the descriptor points to before the start */
    for (int i = 0; i < 64; i++) {
        CHECK(((unsigned char *)&tx_buffer)[i] == (unsigned char)(i + 1));
    }

    /* XEmacPsSendHandler wakes the sender up again */
    do_unblock(net_send_queue.next);
    send_transaction = 0;
    CHECK(test_pcb.status == TASK_READY);
}

int run_tests(void)
{
    host_phys_mem = (unsigned char *)host_calloc(HOST_PHYS_SIZE, 1);
    if (host_phys_mem == NULL) {
        host_printf("p5 net: cannot allocate the simulated physical memory\n");
        return 1;
    }

    test_irq_mode();
    test_poll_recv();
    test_poll_send();
    test_interrupt_recv();
    test_interrupt_send();

    if (failures == 0) {
        host_printf("p5 net: all poll/interrupt send and recv checks passed\n");
    }
    return failures != 0;
}

