/*
 * The maps are bit per object, the lowest bit of a byte first. A set bit means
 * the inode or the block it stands for is taken.
 */
static int map_test(uintptr_t map, uint32_t id)
{
    return (((uint8_t *)map)[id / 8] >> (id % 8)) & 1;
}

static void map_set(uintptr_t map, uint32_t id)
{
    ((uint8_t *)map)[id / 8] |= 1 << (id % 8);
}

static void map_clear(uintptr_t map, uint32_t id)
{
    ((uint8_t *)map)[id / 8] &= ~(1 << (id % 8));
}

/* the first free id of the map, or `num` when everything is taken */
static uint32_t map_first_free(uintptr_t map, uint32_t num)
{
    uint8_t *byte = (uint8_t *)map;

    for (uint32_t i = 0; i < num / 8; i++) {
        if (byte[i] == 0xff) {
            continue;
        }
        for (uint32_t bit = 0; bit < 8; bit++) {
            if ((byte[i] & (1 << bit)) == 0) {
                return i * 8 + bit;
            }
        }
    }
    return num;
}

// Returns inode id
uint16_t alloc_inode()
{
    read_inodemap();
    uint32_t id = map_first_free(inodemap, INODE_NUM);
    if (id == INODE_NUM) {
        /* the file system is out of inodes */
        return INVALID_INODE;
    }
    map_set(inodemap, id);
    write_inodemap();

    read_superblock();
    superblock->used_inode_num++;
    write_superblock();

    return (uint16_t)id;
}

// Returns block id
uint32_t alloc_block()
{
    read_blockmap();
    uint32_t id = map_first_free(blockmap, BLOCK_NUM);
    if (id == BLOCK_NUM) {
        /* the file system is out of blocks */
        return INVALID_BLOCK;
    }
    map_set(blockmap, id);
    write_blockmap();

    read_superblock();
    superblock->used_block_num++;
    write_superblock();

    return id;
}

void free_inode(uint16_t inode_id)
{
    if (inode_id >= INODE_NUM) {
        return;
    }

    read_inodemap();
    if (!map_test(inodemap, inode_id)) {
        /* it is free already, the used counter must not drift */
        return;
    }
    map_clear(inodemap, inode_id);
    write_inodemap();

    read_superblock();
    superblock->used_inode_num--;
    write_superblock();
}

void free_block(uint32_t block_id)
{
    if (block_id >= BLOCK_NUM) {
        return;
    }

    read_blockmap();
    if (!map_test(blockmap, block_id)) {
        return;
    }
    map_clear(blockmap, block_id);
    write_blockmap();

    read_superblock();
    superblock->used_block_num--;
    write_superblock();
}

