} superblock_t;

// 64 bytes
typedef struct inode{
    uint32_t mode;
    uint32_t owner;
    uint32_t size;
    uint32_t direct_blocks[10];
    uint32_t indirect_blocks[2];
    uint32_t link;
} inode_t;

#define EMPTY 0
#define DIR   1
#define FILE  2
// 32 bytes
typedef struct dir_entry{
    uint8_t type;
    uint8_t name[29];
    uint16_t inode;
} dir_entry_t;
// 4096 bytes
typedef struct dir{
    dir_entry_t entry[128];
} dir_t;

